:root {
  --bg: #eef2f6;
  --surface: #ffffff;
  --surface-soft: #f8fafc;
  --surface-muted: #f1f5f9;
  --line: #dbe3ec;
  --line-strong: #c8d3df;

  --text: #172033;
  --text-soft: #5f6b7a;
  --text-faint: #8994a3;

  --primary: #1f5fae;
  --primary-dark: #194f91;
  --primary-soft: #eaf2fb;

  --success: #17865f;
  --success-soft: #e7f6f0;

  --warning: #b87412;
  --warning-soft: #fff4df;

  --danger: #c84c4c;
  --danger-soft: #fdecec;

  --shadow-sm: 0 4px 14px rgba(30, 45, 70, 0.06);
  --shadow-md: 0 14px 34px rgba(30, 45, 70, 0.12);
  --shadow-lg: 0 24px 70px rgba(18, 30, 50, 0.22);

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 18px;

  --header-height: 72px;
  --content-width: 1480px;
}

* {
  box-sizing: border-box;
}

html {
  min-width: 1180px;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  color: var(--text);
  font-family:
    Pretendard,
    "Noto Sans KR",
    "Apple SD Gothic Neo",
    "Malgun Gothic",
    Arial,
    sans-serif;
  font-size: 14px;
  line-height: 1.5;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  border: 0;
}

button,
select {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

[hidden] {
  display: none !important;
}

.app-shell {
  min-height: 100vh;
}

.app-header {
  position: sticky;
  top: 0;
  z-index: 80;
  height: var(--header-height);
  background: rgba(255, 255, 255, 0.98);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(14px);
}

.app-header__inner,
.top-tabs__inner,
.app-main {
  width: min(calc(100% - 48px), var(--content-width));
  margin: 0 auto;
}

.app-header__inner {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.brand__mark {
  display: inline-grid;
  place-items: center;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  border-radius: 12px;
  background: linear-gradient(135deg, #1d5da8, #2e79c9);
  color: #fff;
  font-weight: 900;
  letter-spacing: -0.03em;
  box-shadow: 0 8px 18px rgba(31, 95, 174, 0.24);
}

.brand__text {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.brand__text strong {
  color: #1a2740;
  font-size: 18px;
  letter-spacing: 0.06em;
}

.brand__text small {
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 600;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.header-action {
  min-height: 36px;
  padding: 0 12px;
  border-radius: 8px;
  background: transparent;
  color: #4d5a6c;
  font-size: 13px;
  font-weight: 700;
  transition:
    background 0.16s ease,
    color 0.16s ease;
}

.header-action:hover {
  background: var(--surface-muted);
  color: var(--primary);
}

.header-user {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-left: 6px;
  padding-left: 14px;
  border-left: 1px solid var(--line);
}

.header-user__name {
  color: #29364a;
  font-weight: 800;
}

.header-action--logout {
  color: var(--text-soft);
}

.top-tabs {
  position: sticky;
  top: var(--header-height);
  z-index: 70;
  background: #fff;
  border-bottom: 1px solid var(--line);
}

.top-tabs__inner {
  display: flex;
  align-items: stretch;
  height: 52px;
}

.top-tab {
  position: relative;
  min-width: 92px;
  padding: 0 22px;
  background: transparent;
  color: var(--text-soft);
  font-size: 14px;
  font-weight: 800;
}

.top-tab::after {
  content: "";
  position: absolute;
  right: 20px;
  bottom: -1px;
  left: 20px;
  height: 3px;
  border-radius: 999px 999px 0 0;
  background: transparent;
}

.top-tab:hover,
.top-tab.is-active {
  color: var(--primary);
}

.top-tab.is-active::after {
  background: var(--primary);
}

.app-main {
  padding: 28px 0 56px;
}

.page-view {
  display: none;
}

.page-view.is-active {
  display: block;
}

.content-section {
  margin-bottom: 22px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}

.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 20px;
}

.section-heading--with-action {
  align-items: center;
}

.section-heading__eyebrow {
  margin: 0 0 3px;
  color: var(--primary);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.section-heading__title {
  display: flex;
  align-items: center;
  gap: 8px;

  color: #111827;

  font-size: 31px;
  font-weight: 800;
  line-height: 1.1;

  letter-spacing: -0.04em;
}

.shift-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--text-soft);
}

.shift-summary__label {
  font-size: 12px;
  font-weight: 700;
}

.shift-summary__value {
  color: #24334c;
  font-size: 14px;
}

/* =========================================================
   근무자 현황
========================================================= */

.shift-member-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 10px;
  width: 100%;
}

.shift-member-card {
  position: relative;
  min-width: 0;

  padding: 11px 12px 10px;

  border: 1px solid #4b5563;
  border-radius: 10px;

  background: #ffffff;

  box-shadow:
    0 2px 8px
    rgba(15, 23, 42, 0.05);

  overflow: hidden;
}

.shift-member-card__role {
  margin-bottom: 6px;

  color: #4b5563;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.2;

  letter-spacing: -0.02em;
}

.shift-member-card__body {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;

  margin-bottom: 8px;
  padding: 7px 8px;

  border-radius: 7px;

  background: #f8fafc;
}

.shift-member-card__name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;

  color: #111827;
  font-size: 17px;
  font-weight: 800;
  line-height: 1.25;

  letter-spacing: -0.03em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shift-member-card__team {
  flex: 0 0 auto;
  color: #6b7280;
  font-size: 11px;
  font-weight: 600;
  line-height: 1;
}

.shift-member-card__status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;

  min-height: 24px;
  padding: 0 9px;

  border: 1px solid transparent;
  border-radius: 999px;

  font-size: 11px;
  font-weight: 800;
  line-height: 1;

  white-space: nowrap;
}


/*
  상태 앞 공통 점
*/
.shift-member-card__status::before {
  content: "";
  display: inline-block;
  flex: 0 0 auto;

  width: 7px;
  height: 7px;

  border-radius: 50%;
  background: currentColor;
}

.shift-member-card__status.is-complete {
  border-color: #9fd4b6;
  background: #e8f8ef;
  color: #16804f;
}

.shift-member-card__status.is-writing {
  border-color: #a9c5ea;
  background: #eaf2fd;
  color: #1f5fae;
}

.shift-member-card__status.is-empty {
  border-color: #d3d8df;
  background: #f3f5f7;
  color: #7a8491;
}

@media (max-width: 1200px) {
  .shift-member-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}


.date-navigation-section {
  display: grid;
  grid-template-columns: 46px minmax(380px, 1fr) 46px auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 22px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow-sm);
}

.date-nav-button {
  width: 46px;
  height: 46px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: #fff;
  color: #42516a;
  font-size: 28px;
  line-height: 1;
  transition:
    border-color 0.16s ease,
    background 0.16s ease;
}

.date-nav-button:hover {
  border-color: #aebdce;
  background: var(--surface-soft);
}

.date-navigation__center {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-width: 0;
}

.date-navigation__label {
  margin: 0;
  color: var(--text-faint);
  font-size: 12px;
  font-weight: 700;
}

.date-navigation__date {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  background: transparent;
  color: #22324c;
}

.date-navigation__date strong {
  font-size: 18px;
  letter-spacing: -0.02em;
}

.shift-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 40px;
  min-height: 27px;
  padding: 0 9px;
  border-radius: 999px;
  background: #223c5f;
  color: #fff;
  font-size: 12px;
  font-weight: 900;
}

.today-button {
  min-height: 40px;
  padding: 0 16px;
  border-radius: 9px;
  background: #edf2f7;
  color: #4a5a70;
  font-size: 13px;
  font-weight: 900;
}

.primary-button,
.secondary-button,
.approval-button,
.add-entry-button {
  min-height: 40px;
  padding: 0 16px;
  border-radius: 9px;
  font-size: 13px;
  font-weight: 900;
  transition:
    transform 0.14s ease,
    background 0.16s ease,
    border-color 0.16s ease;
}

.primary-button {
  background: var(--primary);
  color: #fff;
  box-shadow: 0 7px 16px rgba(31, 95, 174, 0.18);
}

.primary-button:hover {
  background: var(--primary-dark);
}

.secondary-button {
  border: 1px solid var(--line-strong);
  background: #fff;
  color: #49576b;
}

.secondary-button:hover {
  background: var(--surface-soft);
}

.approval-button {
  background: #203b60;
  color: #fff;
}

.approval-button:hover {
  background: #172f50;
}

.primary-button:active,
.secondary-button:active,
.approval-button:active,
.add-entry-button:active {
  transform: translateY(1px);
}

.log-table-wrap {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: #fff;
}

.log-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.log-table th,
.log-table td {
  border-bottom: 1px solid var(--line);
  vertical-align: middle;
}

.log-table th {
  height: 46px;
  padding: 0 13px;
  background: #f1f5f9;
  color: #4b5b71;
  font-size: 12px;
  font-weight: 900;
  text-align: center;
}

.log-table td {
  padding: 14px 13px;
  color: #334158;
}

.log-table tbody tr:last-child td {
  border-bottom: 0;
}

.log-table tbody tr:hover {
  background: #fbfcfe;
}

.log-table th:nth-child(1),
.log-table td:nth-child(1) {
  width: 90px;
}

.log-table th:nth-child(2),
.log-table td:nth-child(2) {
  width: 100px;
}

.log-table th:nth-child(3),
.log-table td:nth-child(3) {
  width: 110px;
}

.log-table th:nth-child(4),
.log-table td:nth-child(4) {
  width: 72px;
}

.log-table th:nth-child(6),
.log-table td:nth-child(6) {
  width: 130px;
}

.log-row__role,
.log-row__author {
  text-align: center;
  font-size: 15px;
  font-weight: 800;
  color: #22324c;
}

.log-row__role {
  font-weight: 900;
  color: #2a3c56;
}

.status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 72px;
  min-height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 900;
}

.status-badge.is-approved {
  background: var(--success-soft);
  color: var(--success);
}

.status-badge.is-writing {
  background: var(--warning-soft);
  color: var(--warning);
}

.status-badge.is-saved {
  background: var(--primary-soft);
  color: var(--primary);
}

/* =========================================================
   업무일지 메인 목록
   첨부 표시 + 업무내용 미리보기
========================================================= */


/* =========================================================
   메인 목록 셀 정렬
========================================================= */

.log-row__author-cell,
.log-row__status-cell,
.log-row__attachment-cell,
.log-row__actions-cell {
  text-align: center;
}

.log-row__preview-cell {
  padding-top: 12px !important;
  padding-bottom: 12px !important;
  text-align: left;
}


/* =========================================================
   첨부파일 표시
========================================================= */

.attachment-indicator {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  min-height: 30px;
  padding: 0 7px;
  border: 1px solid #cddaea;
  border-radius: 8px;
  background: #edf4fb;
  color: var(--primary);
  font-size: 16px;
  line-height: 1;
  cursor: default;
}

.attachment-indicator.is-empty {
  border-color: transparent;
  background: transparent;
  color: #a7b0bc;
  font-size: 13px;
}


/* =========================================================
   업무내용 전체 버튼
========================================================= */

.log-preview {
  display: flex;
  width: 100%;
  min-width: 0;
  flex-direction: column;
  gap: 6px;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
  cursor: pointer;
}

.log-preview:hover .log-preview__text {
  color: var(--primary);
}

.log-preview:focus-visible {
  outline: 2px solid rgba(31, 95, 174, 0.28);
  outline-offset: 4px;
  border-radius: 5px;
}


/* =========================================================
   업무내용 한 줄

   첫 번째 열: 운전현황·TM·인계·비고
   두 번째 열: TAG + 번호 + 시간 + 내용
========================================================= */

.log-preview__group {
  display: grid;
  width: 100%;
  min-width: 0;
  grid-template-columns: 76px minmax(0, 1fr);
  align-items: start;
  column-gap: 10px;
}


/*
   같은 분류의 두 번째 항목부터는 제목 요소가 없다.

   제목 배지는 출력하지 않으면서
   내용은 기존 두 번째 열에 그대로 배치한다.
*/
.log-preview__group.has-no-title
.log-preview__content {
  grid-column: 2;
}


/* =========================================================
   운전현황·TM·인계·비고 제목
========================================================= */

.log-preview__title {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 24px;
  padding: 3px 8px;
  border-radius: 6px;
  background: #edf2f7;
  color: #42536a;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.35;
  white-space: nowrap;
}

.log-preview__group.is-operation
.log-preview__title {
  background: #eaf2fb;
  color: var(--primary);
}

.log-preview__group.is-maintenance
.log-preview__title {
  background: #e7f6f0;
  color: var(--success);
}

.log-preview__group.is-handover
.log-preview__title {
  background: #fff4df;
  color: var(--warning);
}

.log-preview__group.is-note
.log-preview__title {
  background: #f1f3f5;
  color: #667181;
}


/* =========================================================
   제목 오른쪽의 TAG·번호·시간·내용
========================================================= */

.log-preview__content {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: 7px;
  padding-top: 2px;
  color: #34445a;
  font-size: 13px;
  line-height: 1.55;
  text-align: left;
}


/* =========================================================
   TAG 표시
========================================================= */

.log-preview__tag {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  min-height: 22px;
  padding: 1px 6px;
  border-radius: 5px;
  background: var(--primary-soft);
  color: var(--primary);
  font-family:
    Consolas,
    "Courier New",
    monospace;
  font-size: 11px;
  font-weight: 800;
  line-height: 1.5;
  white-space: nowrap;
}


/* =========================================================
   업무내용 글씨
========================================================= */

.log-preview__text {
  display: block;
  min-width: 0;
  overflow: visible;
  color: #34445a;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.55;
  text-align: left;
  white-space: normal;
  word-break: break-word;
  overflow-wrap: anywhere;
  transition: color 0.16s ease;
}


/* =========================================================
   표시할 내용이 없을 때
========================================================= */

.log-preview__empty {
  display: block;
  padding: 5px 0;
  color: var(--text-faint);
  font-size: 12px;
  text-align: left;
}

/* =========================================================
  업무일지 목록 관리 버튼 최종본

  위:
  이어쓰기 또는 수정

  아래:
  삭제
========================================================= */


/* =========================================================
  관리 열
========================================================= */

.log-table th:nth-child(6),
.log-table td:nth-child(6) {
  width: 92px;
}


.log-row__actions-cell {
  padding-right: 8px !important;
  padding-left: 8px !important;

  text-align: center;
  vertical-align: middle !important;
}


/* =========================================================
  버튼 세로 배치
========================================================= */

.row-actions {
  display: flex;
  width: 100%;
  height: 100%;

  flex-direction: column;
  align-items: center;
  justify-content: center;

  gap: 5px;

  margin: 0;
  padding: 0;
}


/* =========================================================
  공통 버튼
========================================================= */

.table-action-button {
  display: inline-flex;
  width: 74px;
  min-width: 74px;
  height: 29px;
  min-height: 29px;

  align-items: center;
  justify-content: center;

  margin: 0;
  padding: 0 8px;

  border: 1px solid #abc2dd;
  border-radius: 7px;

  background: #ffffff;
  color: #245f9e;

  font-size: 11px;
  font-weight: 900;
  line-height: 1;

  text-align: center;
  white-space: nowrap;

  transition:
    border-color 0.15s ease,
    background 0.15s ease,
    color 0.15s ease,
    transform 0.12s ease;
}


.table-action-button:hover {
  border-color: #6e9dce;
  background: #eef5fc;
  color: #174f8c;
}


.table-action-button:active {
  transform: translateY(1px);
}


/* =========================================================
  삭제 버튼
========================================================= */

.table-action-button.is-delete {
  border-color: #e5bcbc;
  background: #fffafa;
  color: #bb3f3f;
}


.table-action-button.is-delete:hover {
  border-color: #d37878;
  background: #fff0f0;
  color: #a72f2f;
}


/* =========================================================
  버튼 키보드 선택
========================================================= */

.table-action-button:focus-visible {
  outline: 2px solid rgba(31, 95, 174, 0.25);
  outline-offset: 2px;
}


/* =========================================================
  작은 화면
========================================================= */

@media (max-width: 760px) {
  .log-table th:nth-child(6),
  .log-table td:nth-child(6) {
    width: 82px;
  }

  .table-action-button {
    width: 66px;
    min-width: 66px;
    height: 28px;
    min-height: 28px;
    font-size: 10px;
  }
}

.empty-state {
  padding: 52px 20px;
  color: var(--text-soft);
  text-align: center;
}

.empty-state strong {
  display: block;
  margin-bottom: 6px;
  color: #344257;
  font-size: 16px;
}

.empty-state p {
  margin: 0;
}

.search-form {
  margin-bottom: 22px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface-soft);
}

.search-form__grid {
  display: grid;
  grid-template-columns:
    minmax(140px, 0.8fr)
    minmax(140px, 0.8fr)
    minmax(120px, 0.65fr)
    minmax(120px, 0.65fr)
    minmax(140px, 0.75fr)
    minmax(280px, 1.7fr);
  gap: 12px;
}

.search-form__actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 16px;
}

.search-result-header {
  margin-bottom: 10px;
  color: #344257;
}

.search-result-header span {
  color: var(--primary);
}

/* =========================================================
  업무일지 조회 결과 최종 디자인

  열 순서:
  일자 | 근무 | 보직 | 작성자 | 업무 내용 | 보기 | 첨부

  업무 내용 열이 남은 공간을 전부 사용한다.
========================================================= */

.search-log-table-wrap {
  width: 100%;
  overflow-x: auto;
}


/* =========================================================
  표 전체
========================================================= */

.search-result-table {
  width: 100%;
  min-width: 1080px;
  table-layout: fixed;
}


/* =========================================================
  열 너비

  고정 열을 제외한 남은 공간은
  다섯 번째 업무 내용 열이 전부 사용한다.
========================================================= */

.search-result-table th:nth-child(1),
.search-result-table td:nth-child(1) {
  width: 100px;
}


.search-result-table th:nth-child(2),
.search-result-table td:nth-child(2) {
  width: 64px;
}


.search-result-table th:nth-child(3),
.search-result-table td:nth-child(3) {
  width: 76px;
}


.search-result-table th:nth-child(4),
.search-result-table td:nth-child(4) {
  width: 92px;
}


.search-result-table th:nth-child(5),
.search-result-table td:nth-child(5) {
  width: auto;
}


.search-result-table th:nth-child(6),
.search-result-table td:nth-child(6) {
  width: 78px;
}


.search-result-table th:nth-child(7),
.search-result-table td:nth-child(7) {
  width: 52px;
}


/* =========================================================
  기본 셀 정렬
========================================================= */

.search-result-table th {
  padding-right: 10px;
  padding-left: 10px;
  text-align: center;
}


.search-result-table td {
  padding: 12px 10px;
  vertical-align: middle;
}


.search-log-date-cell,
.search-log-shift-cell,
.search-log-role-cell,
.search-log-author-cell,
.search-log-view-cell,
.search-log-attachment-cell {
  text-align: center;
}


.search-log-date-cell,
.search-log-shift-cell {
  color: #526177;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}


.search-log-role-cell {
  color: #22324c;
  font-size: 13px;
  font-weight: 900;
  white-space: nowrap;
}


.search-log-author-cell strong {
  display: block;
  overflow: hidden;
  color: #22324c;
  font-size: 13px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}


/* =========================================================
  업무 내용 열

  남은 가로 공간을 모두 사용한다.
========================================================= */

.search-log-preview-cell {
  min-width: 0;
  padding: 10px 14px !important;
  text-align: left !important;
  vertical-align: top !important;
}


.search-log-preview {
  display: flex;
  width: 100%;
  min-width: 0;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  text-align: left;
}


/*
  조회 화면에서는 메인 업무일지와 같은 구조를 사용하되,
  분류 제목 너비를 조금 줄여 업무 내용을 더 넓게 표시한다.
*/
.search-log-preview .log-preview__group {
  grid-template-columns:
    82px
    minmax(0, 1fr);
  column-gap: 9px;
  padding-right: 2px;
  padding-left: 2px;
}


.search-log-preview
.log-preview__group.has-no-title {
  grid-template-columns:
    82px
    minmax(0, 1fr);
}


.search-log-preview
.log-preview__group.has-no-title::before {
  width: 82px;
}


.search-log-preview .log-preview__title {
  width: 82px;
  min-width: 82px;
}


.search-log-preview .log-preview__role-section {
  padding-right: 2px;
  padding-left: 2px;
}


.search-log-preview .log-preview__role-divider {
  width: 82px;
  min-width: 82px;
  margin-left: 0;
}


/* =========================================================
  업무 내용 글씨
========================================================= */

.search-log-preview .log-preview__content {
  min-width: 0;
}


.search-log-preview .log-preview__text {
  min-width: 0;
  color: #26364b;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.55;
  text-align: left;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: anywhere;
}


/* =========================================================
  보기 버튼
========================================================= */

.search-log-view-cell {
  padding-right: 6px !important;
  padding-left: 6px !important;
}


.search-log-view-cell .table-action-button {
  width: 60px;
  min-width: 60px;
  height: 29px;
  min-height: 29px;
  padding: 0 6px;
}


/* =========================================================
  첨부
========================================================= */

.search-log-attachment-cell {
  padding-right: 5px !important;
  padding-left: 5px !important;
}


.search-log-attachment-cell
.attachment-indicator {
  min-width: 27px;
  min-height: 27px;
  padding: 0 5px;
  font-size: 12px;
}


/* =========================================================
  조회 표 전용 세로 구분선

  작성자와 업무 내용 사이,
  업무 내용과 보기 사이만 표시한다.
========================================================= */

.search-result-table th,
.search-result-table td {
  border-right: 0 !important;
  border-left: 0 !important;
}


.search-result-table th:nth-child(5),
.search-result-table td:nth-child(5) {
  border-right: 1px solid #d9e3ed !important;
  border-left: 1px solid #d9e3ed !important;
}


/* =========================================================
  행 효과
========================================================= */

.search-result-table
tbody tr:hover td {
  background: #f8fbff;
}


/* =========================================================
  좁은 화면
========================================================= */

@media (max-width: 1200px) {
  .search-result-table {
    min-width: 1040px;
  }


  .search-result-table th:nth-child(1),
  .search-result-table td:nth-child(1) {
    width: 94px;
  }


  .search-result-table th:nth-child(4),
  .search-result-table td:nth-child(4) {
    width: 84px;
  }


  .search-log-preview .log-preview__group,
  .search-log-preview
  .log-preview__group.has-no-title {
    grid-template-columns:
      76px
      minmax(0, 1fr);
  }


  .search-log-preview
  .log-preview__group.has-no-title::before,
  .search-log-preview .log-preview__title,
  .search-log-preview .log-preview__role-divider {
    width: 76px;
    min-width: 76px;
  }
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.form-field__label {
  color: #4f5f74;
  font-size: 12px;
  font-weight: 900;
}

.form-field input,
.form-field select,
.form-field textarea,
.large-textarea,
.editor-section > textarea {
  width: 100%;
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  background: #fff;
  color: var(--text);
  outline: none;
  transition:
    border-color 0.16s ease,
    box-shadow 0.16s ease;
}

.form-field input,
.form-field select {
  min-height: 41px;
  padding: 0 11px;
}

.form-field textarea,
.large-textarea,
.editor-section > textarea {
  resize: vertical;
  padding: 11px 12px;
  line-height: 1.65;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus,
.large-textarea:focus,
.editor-section > textarea:focus {
  border-color: #6b9bcf;
  box-shadow: 0 0 0 3px rgba(31, 95, 174, 0.1);
}

.form-field--wide {
  grid-column: auto;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 28px;
  background: rgba(18, 27, 42, 0.56);
}

.modal-backdrop.is-open {
  display: flex;
}

.modal-panel {
  width: min(1120px, calc(100vw - 56px));
  max-height: calc(100vh - 56px);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 18px;
  background: #fff;
  box-shadow: var(--shadow-lg);
}

.log-detail-modal {
  width: min(920px, calc(100vw - 56px));
}

.modal-header {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  min-height: 72px;
  padding: 16px 22px;
  border-bottom: 1px solid var(--line);
  background: #fff;
}

.modal-header__eyebrow {
  margin: 0 0 2px;
  color: var(--primary);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.14em;
}

.modal-header__title {
  margin: 0;
  color: #1b2840;
  font-size: 22px;
  letter-spacing: -0.03em;
}

.modal-close-button {
  width: 38px;
  height: 38px;
  border-radius: 9px;
  background: #f1f4f7;
  color: #596678;
  font-size: 25px;
  line-height: 1;
}

.modal-close-button:hover {
  background: #e8edf2;
}

.modal-body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 20px 22px 26px;
  background: #f7f9fb;
}

.editor-section {
  margin-bottom: 16px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: #fff;
}

.editor-section:last-child {
  margin-bottom: 0;
}

.editor-section__heading {
  margin-bottom: 14px;
}

.editor-section__heading--with-action {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.editor-section__heading h3 {
  margin: 0;
  color: #27364d;
  font-size: 16px;
}

.editor-section__heading p {
  margin: 3px 0 0;
  color: var(--text-faint);
  font-size: 12px;
}

/* =========================================================
   기본 정보
   작성일 | 근무 | 보직 | 작성자 | 대근
========================================================= */

.basic-info-grid {
  display: grid;
  grid-template-columns:
    minmax(180px, 1.15fr)
    minmax(190px, 1fr)
    minmax(150px, 0.85fr)
    minmax(190px, 1.15fr)
    minmax(105px, 0.55fr);
  align-items: end;
  gap: 12px;
  width: 100%;
}


/*
  근무파트는 스크립트의 자동 계산 및 저장을 위해
  HTML 요소만 유지하고 화면에서는 표시하지 않는다.
*/
.basic-info-hidden-team {
  display: none !important;
}


/*
  대근 칸이 다른 입력칸과 같은 높이로
  한 줄에 정렬되도록 한다.
*/
.substitute-work-field {
  min-width: 0;
}


/* =========================================================
   기본 정보 반응형
========================================================= */

@media (max-width: 1000px) {
  .basic-info-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .substitute-work-field {
    grid-column: auto;
  }
}


@media (max-width: 640px) {
  .basic-info-grid {
    grid-template-columns: 1fr;
  }
}
.add-entry-button {
  flex: 0 0 auto;
  border: 1px solid #bfd0e2;
  background: #edf4fb;
  color: var(--primary);
}

.add-entry-button:hover {
  background: #e3eef9;
}

/* =========================================================
   현재 운전현황 v2
========================================================= */

.operation-status-section {
  overflow: visible;
}


/* =========================================================
   상단 제목과 수정 버튼
========================================================= */

.operation-status-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.operation-status-heading > div {
  min-width: 0;
}

.operation-status-edit-button {
  flex: 0 0 auto;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid #b8cbe0;
  border-radius: 9px;
  background: #eef5fc;
  color: var(--primary);
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}

.operation-status-edit-button:hover {
  border-color: #8eafd2;
  background: #e2eef9;
}

.operation-status-edit-button.is-active {
  border-color: #d3a249;
  background: #fff4dc;
  color: #92610e;
}


/* =========================================================
   현재 적용 중인 운전현황 카드
========================================================= */

.operation-status-current-card {
  position: relative;
  overflow: hidden;
  padding: 18px;
  border: 1px solid #c9d9e9;
  border-radius: 12px;
  background:
    linear-gradient(
      135deg,
      #f7fbff 0%,
      #ffffff 65%
    );
}

.operation-status-current-card::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 4px;
  background: var(--primary);
}

.operation-status-current-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 13px;
}

.operation-status-current-title {
  display: flex;
  align-items: center;
  gap: 8px;
}

.operation-status-current-title strong {
  color: #263750;
  font-size: 13px;
}

.operation-status-live-dot {
  position: relative;
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--success);
  box-shadow:
    0 0 0 4px rgba(23, 134, 95, 0.12);
}

.operation-status-live-dot::after {
  content: "";
  position: absolute;
  inset: -4px;
  border: 1px solid rgba(23, 134, 95, 0.35);
  border-radius: 50%;
}


/* =========================================================
   상태 배지
========================================================= */

.operation-status-state-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 27px;
  padding: 0 10px;
  border-radius: 999px;
  background: var(--success-soft);
  color: var(--success);
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.operation-status-state-badge.is-normal {
  background: var(--success-soft);
  color: var(--success);
}

.operation-status-state-badge.is-planned {
  background: var(--warning-soft);
  color: var(--warning);
}

.operation-status-state-badge.is-emergency,
.operation-status-state-badge.is-stopped {
  background: var(--danger-soft);
  color: var(--danger);
}

.operation-status-state-badge.is-other {
  background: var(--primary-soft);
  color: var(--primary);
}


/* =========================================================
   현재 운전현황 본문
========================================================= */

.operation-status-current-content {
  min-height: 74px;
  padding: 13px 14px;
  border: 1px solid #dae5ef;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.88);
  color: #2f4057;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.75;
  white-space: pre-wrap;
  word-break: break-word;
}


/* =========================================================
   마지막 수정 정보
========================================================= */

.operation-status-current-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 11px;
  color: var(--text-faint);
  font-size: 11px;
}

.operation-status-current-meta strong {
  color: #5b6879;
  font-size: 11px;
}

.operation-status-meta-divider {
  color: #abb4bf;
}


/* =========================================================
   운전현황 수정 영역
========================================================= */

.operation-status-editor {
  margin-top: 14px;
  padding: 16px;
  border: 1px solid #d5dee8;
  border-radius: 12px;
  background: #f8fafc;
}

.operation-status-editor[hidden] {
  display: none !important;
}

.operation-status-editor-grid {
  display: grid;
  grid-template-columns: 180px minmax(0, 1fr);
  align-items: start;
  gap: 14px;
}

.operation-status-editor-content textarea {
  min-height: 132px;
  max-height: 260px;
  resize: vertical;
}

.operation-status-editor-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 14px;
}


/* =========================================================
   수정 중 상태
========================================================= */

.operation-status-section.is-editing
.operation-status-current-card {
  border-color: #e0b765;
  background: #fffdf8;
}

.operation-status-section.is-editing
.operation-status-current-card::before {
  background: #d59a2c;
}


/* =========================================================
   반응형
========================================================= */

@media (max-width: 760px) {
  .operation-status-heading {
    align-items: stretch;
    flex-direction: column;
    gap: 10px;
  }

  .operation-status-edit-button {
    align-self: flex-end;
  }

  .operation-status-current-card {
    padding: 15px;
  }

  .operation-status-current-header {
    align-items: flex-start;
  }

  .operation-status-editor-grid {
    grid-template-columns: 1fr;
  }

  .operation-status-editor-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }

  .operation-status-editor-actions button {
    width: 100%;
  }
}

/* =========================================================
   작업 · 정비 · 인계 내역
   컴팩트 입력 영역
========================================================= */

.log-entry-section {
  overflow: visible;
}


/* =========================================================
   입력 패널
========================================================= */

.log-entry-input-panel {
  padding: 13px 16px 14px;
  border: 1px solid #d7e0e9;
  border-radius: 11px;
  background: #f8fafc;
}


/* =========================================================
   상단 입력 영역

   구분 | 시간 + 현재시간 | TAG | 추가
========================================================= */

.log-entry-input-top-row {
  display: grid;
  grid-template-columns:
    210px
    190px
    minmax(240px, 1fr)
    auto;
  align-items: end;
  gap: 9px;
  width: 100%;
}

.log-entry-input-panel .form-field {
  min-width: 0;
  gap: 4px;
}

.log-entry-input-panel .form-field__label {
  color: #48586e;
  font-size: 10px;
  font-weight: 900;
  line-height: 1.25;
}


/* =========================================================
   상단 공통 입력칸
========================================================= */

.log-entry-input-panel
.form-field input,
.log-entry-input-panel
.form-field select {
  width: 100%;
  min-height: 36px;
  padding: 0 10px;
  border: 1px solid #c8d4e1;
  border-radius: 7px;
  background: #ffffff;
  color: #26364c;
  font-size: 12px;
}

.log-entry-input-panel
.form-field input:focus,
.log-entry-input-panel
.form-field select:focus {
  border-color: #78a3d1;
  box-shadow:
    0 0 0 3px
    rgba(31, 95, 174, 0.09);
}


/* =========================================================
   구분
========================================================= */

.log-entry-field--category {
  min-width: 0;
}

.log-entry-field--category select {
  font-weight: 700;
}


/* =========================================================
   시간 + 현재시간
========================================================= */

.log-entry-field--time {
  min-width: 0;
}

.log-entry-time-group {
  display: grid;
  grid-template-columns:
    minmax(0, 1fr)
    auto;
  align-items: center;
  gap: 6px;
}

.log-entry-time-group
#logEntryTime {
  width: 100%;
  min-width: 0;
  min-height: 36px;
  padding: 0 9px;
  border-radius: 7px;
}

.current-time-check {
  display: inline-flex;
  flex: 0 0 auto;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0 9px;
  border: 1px solid #c8d4e1;
  border-radius: 7px;
  background: #ffffff;
  color: #5c697b;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  user-select: none;
  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}

.current-time-check:hover {
  border-color: #9eb8d3;
  background: #f3f7fb;
}

.current-time-check:has(
  input:checked
) {
  border-color: #8bb1dc;
  background: #eaf2fb;
  color: #1f5fae;
}

