}

.log-entry-empty-row td {
  height: 74px;
  color: #8a96a5;
  text-align: center !important;
}


/* =========================================================
   내용 표시
========================================================= */

.log-entry-content {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  text-align: left;
}

.log-entry-content__tag {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 2px 8px;
  border-radius: 7px;
  background: #eaf3fc;
  color: var(--primary);
  font-family:
