}

.log-entry-content__text {
  min-width: 0;
  color: #35445a;
  line-height: 1.6;
  text-align: left;
  white-space: pre-wrap;
  word-break: break-word;
}


/* =========================================================
   수정 · 삭제 버튼
========================================================= */

.log-entry-row-actions {
