  align-items: center;
  justify-content: center;
  gap: 5px;
}

.log-entry-edit-button,
.log-entry-delete-button {
  min-height: 30px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #fff;
  font-size: 11px;
  font-weight: 900;
  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}

.log-entry-edit-button {
  color: var(--primary);
}

.log-entry-edit-button:hover {
  border-color: #9eb9d7;
  background: var(--primary-soft);
}

.log-entry-delete-button {
  color: var(--danger);
}

.log-entry-delete-button:hover {
  border-color: #e5b6b6;
  background: var(--danger-soft);
}


/* =========================================================
   수정 중 표시
========================================================= */

.log-entry-table tr.is-editing {
  background: #fff8e8;
}

.log-entry-table tr.is-editing:hover {
  background: #fff8e8;
}

.log-entry-input-panel.is-editing {
  border-color: #e3b560;
  background: #fffbf2;
}

.log-entry-input-panel.is-editing .add-entry-button {
  border-color: #dca745;
  background: #fff0ce;
  color: #95600b;
}


/* =========================================================
   반응형
========================================================= */

@media (max-width: 1100px) {
  .log-entry-input-top-row {
    grid-template-columns:
      minmax(190px, 1fr)
      minmax(150px, 0.8fr)
      minmax(260px, 1.4fr);
  }

  .log-entry-input-actions {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .log-entry-input-panel {
    padding: 14px;
  }

  .log-entry-input-top-row {
    grid-template-columns: 1fr;
  }

  .log-entry-input-actions {
    grid-column: auto;
  }

  .log-entry-input-actions .secondary-button,
  .log-entry-input-actions .add-entry-button {
    flex: 1 1 0;
  }

  .log-entry-time-group {
    grid-template-columns: minmax(0, 1fr) auto;
