  }
}

.file-dropzone {
  min-height: 132px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  border: 1.5px dashed #b9c8d8;
  border-radius: 11px;
  background: #f8fafc;
  color: #56667b;
  text-align: center;
  transition:
    border-color 0.16s ease,
    background 0.16s ease;
}

.file-dropzone:hover {
  border-color: #6f9dcc;
  background: #f3f8fd;
}

.file-dropzone__icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--primary-soft);
  color: var(--primary);
  font-size: 22px;
  font-weight: 800;
}

.file-dropzone strong {
  color: #3d4d63;
}

.file-dropzone small {
  color: var(--text-faint);
}

.attachment-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.modal-footer {
  flex: 0 0 auto;
  min-height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 13px 22px;
  border-top: 1px solid var(--line);
  background: #fff;
}

.modal-footer__left,
.modal-footer__right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.toast {
  position: fixed;
  right: 26px;
  bottom: 26px;
  z-index: 400;
  max-width: 420px;
  padding: 13px 16px;
  border-radius: 10px;
  background: #21344f;
  color: #fff;
  font-size: 13px;
  font-weight: 700;
  box-shadow: var(--shadow-md);
  opacity: 0;
  pointer-events: none;
  transform: translateY(12px);
  transition:
    opacity 0.2s ease,
    transform 0.2s ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
}

body.modal-open {
  overflow: hidden;
}

@media (max-width: 1320px) {
  .shift-member-grid {
    grid-template-columns: repeat(3, minmax(180px, 1fr));
  }

  .search-form__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .form-field--wide {
    grid-column: span 2;
  }

}

@media print {
  body {
    background: #fff;
  }

  .app-header,
  .top-tabs,
  .date-navigation-section,
  .header-actions,
  .section-heading--with-action .primary-button,
  .row-actions,
  .modal-footer,
  .modal-close-button {
    display: none !important;
  }

  .app-main,
  .content-section,
  .modal-panel,
  .modal-body,
  .editor-section {
    width: 100%;
    max-width: none;
    margin: 0;
    padding: 0;
    border: 0;
    box-shadow: none;
  }

  .modal-backdrop.is-open {
    position: static;
    display: block;
    padding: 0;
    background: transparent;
  }

  .modal-panel {
    max-height: none;
    overflow: visible;
  }

  .modal-body {
    overflow: visible;
    background: #fff;
  }
}

/* =========================================================
  업무일지 상세보기 최종 디자인

  변경사항:
  1. 상세창 폭 확대
  2. 인계 및 작업 내역 최소 5줄 높이 유지
  3. 내용이 많을 경우 자연스럽게 아래로 확장
  4. 모바일에서는 기존처럼 화면 폭에 맞춤
========================================================= */


/* =========================================================
  상세보기 모달 전체 크기
========================================================= */

#logDetailModal
.log-detail-modal {
  display: flex !important;
  flex-direction: column !important;

  width:
    min(
      1240px,
      calc(100vw - 56px)
    ) !important;

  max-width:
    1240px !important;

  height:
    min(
      880px,
      calc(100vh - 52px)
    ) !important;

  max-height:
    calc(100vh - 52px) !important;

  margin:
    26px auto !important;

  border-radius:
    14px !important;

  overflow:
    hidden !important;
}


/* =========================================================
  상세보기 상단
========================================================= */

#logDetailModal
.log-detail-modal__header {
  flex:
    0 0 auto !important;

  min-height:
    70px !important;

  padding:
    15px
    20px !important;
}


/* =========================================================
  상세보기 본문
========================================================= */

#logDetailModal
.log-detail-modal__body {
  flex:
    1 1 auto !important;

  min-width:
    0 !important;

  min-height:
    0 !important;

  width:
    100% !important;

  padding:
    16px
    20px
    20px !important;

  overflow-x:
    hidden !important;

  overflow-y:
    auto !important;
}


/* =========================================================
  상세보기 문서
========================================================= */

#logDetailModal
.shift-log-detail-document {
  display:
    flex !important;

  flex-direction:
    column !important;

  width:
    100% !important;

  min-width:
    0 !important;

  gap:
    14px !important;
}


/* =========================================================
  상세보기 제목
========================================================= */

#logDetailModal
.shift-log-detail-document__title {
  margin:
    0 !important;

  padding:
    0
    2px !important;
}


/* =========================================================
  기본정보 그리드
========================================================= */

#logDetailModal
.shift-log-detail-summary {
  display:
    grid !important;

  grid-template-columns:
    repeat(
      3,
      minmax(
        0,
        1fr
      )
    ) !important;

  gap:
    10px !important;
}


#logDetailModal
.shift-log-detail-summary__item {
  min-width:
    0 !important;

  min-height:
    72px !important;

  padding:
    12px
    14px !important;
}


/* =========================================================
  상세보기 공통 섹션
========================================================= */

#logDetailModal
.shift-log-detail-section {
  width:
    100% !important;

  min-width:
    0 !important;

  margin:
    0 !important;

  border:
    1px solid
    #d7e1ec !important;

  border-radius:
    11px !important;

  background:
    #ffffff !important;

  overflow:
    hidden !important;
}


#logDetailModal
.shift-log-detail-section__header {
  display:
    flex !important;

  align-items:
    center !important;

  justify-content:
    space-between !important;

  min-height:
    62px !important;

  padding:
    11px
    15px !important;

  border-bottom:
    1px solid
    #dce5ee !important;

  background:
    #f8fafc !important;
}


#logDetailModal
.shift-log-detail-section__header
h3 {
  margin:
    2px
    0
    0 !important;

  font-size:
    16px !important;

  font-weight:
    900 !important;

  line-height:
    1.3 !important;
}


#logDetailModal
.shift-log-detail-eyebrow {
  font-size:
    9px !important;

  font-weight:
    900 !important;

  line-height:
    1 !important;

  letter-spacing:
    0.14em !important;
}


#logDetailModal
.shift-log-detail-count {
  flex:
    0 0 auto !important;

  min-width:
    36px !important;

  padding:
    5px
    9px !important;

  text-align:
    center !important;
}


/* =========================================================
  상세보기 공통 본문
========================================================= */

#logDetailModal
.shift-log-detail-section__body {
  display:
    block !important;

  width:
    100% !important;

  min-width:
    0 !important;

  min-height:
    0 !important;

  height:
    auto !important;

  padding:
    13px
    15px !important;
