  flex-direction: column;
  gap: 4px;
}

.member-log-import-button__content strong {
  overflow: hidden;
  color: #173b6d;
  font-size: 13px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.member-log-import-button__content small {
