/* =========================================================
   인수인계사항 구역
   TM 발행 내역 / 인계사항
========================================================= */

.handover-entry-group {
  position: relative;
  margin: 0;
  padding: 0 16px 16px;
  background: #ffffff;
}

.handover-entry-group + .handover-entry-group {
  padding-top: 4px;
}


/* =========================================================
   구역 제목
========================================================= */

.handover-entry-group__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  min-height: 48px;
  margin: 0;
  padding: 12px 2px 9px;
}

.handover-entry-group__header > div {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.handover-entry-group__header strong {
  position: relative;
  display: inline-flex;
  align-items: center;
  color: #26364c;
  font-size: 14px;
  font-weight: 900;
  line-height: 1.3;
  letter-spacing: -0.02em;
}

.handover-entry-group__header strong::before {
  content: "";
  display: inline-block;
  flex: 0 0 auto;
  width: 4px;
  height: 15px;
  margin-right: 8px;
  border-radius: 999px;
  background: #1f5fae;
}


/* =========================================================
   구역별 건수
========================================================= */

.handover-entry-group__count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 38px;
  min-height: 22px;
  padding: 0 8px;
  border-radius: 999px;
  background: #edf2f7;
  color: #657287;
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}


/* =========================================================
   TM 발행 내역
========================================================= */

.handover-entry-group--tm {
  border-bottom: 1px solid #e6ebf1;
}

.handover-entry-group--tm
.handover-entry-group__header strong::before {
  background: #b87412;
}

.handover-entry-group--tm
.handover-entry-group__count {
  background: #fff4df;
  color: #9b650f;
}


/* =========================================================
   인계사항
========================================================= */

.handover-entry-group--handover
.handover-entry-group__header strong::before {
  background: #1f5fae;
}

.handover-entry-group--handover
.handover-entry-group__count {
  background: #eaf2fb;
  color: #1f5fae;
}


/* =========================================================
   각 구역의 표
========================================================= */

.handover-entry-group
.log-entry-table-wrap {
  overflow-x: auto;
  border: 1px solid #dfe5ec;
  border-radius: 10px;
  background: #ffffff;
}

.handover-entry-group
.log-entry-table th {
  height: 38px;
  padding-top: 7px;
  padding-bottom: 7px;
  background: #f6f8fb;
  color: #657287;
  font-size: 11px;
}

.handover-entry-group
.log-entry-table td {
  padding-top: 10px;
  padding-bottom: 10px;
}


/* =========================================================
   빈 목록
========================================================= */

.handover-entry-group
.log-entry-empty-row td {
  height: 70px;
  background: #fbfcfd;
  color: #929cab;
  font-size: 12px;
}


/* =========================================================
   모바일
========================================================= */

@media (max-width: 768px) {
  .handover-entry-group {
    padding-right: 12px;
    padding-left: 12px;
  }

  .handover-entry-group__header {
    min-height: 44px;
    padding-top: 10px;
    padding-bottom: 8px;
  }

  .handover-entry-group__header strong {
    font-size: 13px;
  }

  .handover-entry-group__header strong::before {
    height: 14px;
    margin-right: 7px;
  }
}

/* =========================================================
   인계사항 번호 + 시간 표시
========================================================= */

.log-entry-time-cell {
  width: 112px;
  padding-right: 12px !important;
  padding-left: 12px !important;
  text-align: left !important;
}

.log-entry-time-display {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 7px;
  width: 100%;
  min-width: 0;
  white-space: nowrap;
}

.log-entry-row-number {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  flex: 0 0 22px;
  min-width: 22px;
  color: #1f5fae;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  text-align: right;
}

.log-entry-time-text {
  display: inline-block;
  color: #394a60;
  font-size: 12px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  letter-spacing: 0.01em;
}

.log-entry-content-cell {
  text-align: left;
}

.log-entry-inline-content {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 5px;
  width: 100%;
  min-width: 0;
}

.log-entry-inline-content__text {
  min-width: 0;
  color: #26364b;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.55;
  overflow-wrap: anywhere;
}

.log-entry-inline-tag {
  display: inline;
  flex: 0 0 auto;
  padding: 0;
  border: 0;
  background: transparent;
  color: #1f5fae;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.4;
  white-space: nowrap;
  cursor: pointer;
}

.log-entry-inline-tag:hover {
  color: #164b8a;
  text-decoration: underline;
}


/* =========================================================
   모바일
========================================================= */

@media (max-width: 768px) {
  .log-entry-time-cell {
    width: 100px;
    padding-right: 8px !important;
    padding-left: 8px !important;
  }

  .log-entry-time-display {
    gap: 5px;
  }

  .log-entry-row-number {
    flex-basis: 19px;
    min-width: 19px;
    font-size: 11px;
  }

  .log-entry-time-text {
    font-size: 11px;
  }

  .log-entry-inline-content__text {
    font-size: 12px;
  }

  .log-entry-inline-tag {
    font-size: 10px;
  }
}

