========================================================= */

.handover-entry-group--handover
.log-entry-time-cell {
  width: 112px;
}

.handover-entry-group--handover
.log-entry-content-cell {
  padding-left: 8px;
}


/* =========================================================
   모바일
========================================================= */

@media (max-width: 768px) {
  .handover-entry-group--handover
  .log-entry-table__category,
  .handover-entry-group--handover
  .log-entry-category-cell-wrap {
