.log-report-summary {
  padding: 24px;
  border-radius: 18px;
  border: 1px solid #d8e2ef;
  background: linear-gradient(
    135deg,
    #ffffff,
    #f5f9ff
  );
}

.log-report-summary__top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 22px;
}

.log-report-summary__eyebrow,
.log-report-section__eyebrow {
  display: block;
  margin-bottom: 6px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: .18em;
  color: #6b7280;
}

.log-report-summary h2 {
  margin: 0;
  font-size: 28px;
  font-weight: 800;
}

.log-report-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
}

.log-report-status__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.log-report-status.is-complete {
  background: #e8f8ee;
  color: #0d7a3d;
}

.log-report-status.is-complete
.log-report-status__dot {
  background: #16a34a;
}

.log-report-status.is-writing {
  background: #fff6da;
  color: #8a5a00;
}

.log-report-status.is-writing
.log-report-status__dot {
  background: #f59e0b;
}

.log-report-status.is-saved {
  background: #eef2ff;
  color: #4338ca;
}

.log-report-status.is-saved
.log-report-status__dot {
  background: #6366f1;
}

.log-report-summary__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(150px,1fr));
  gap: 14px;
}

.log-report-summary__item {
  padding: 14px;
  border-radius: 12px;
  background: white;
  border: 1px solid #e5e7eb;
}

.log-report-summary__item span {
  display: block;
  margin-bottom: 6px;
  font-size: 12px;
  color: #6b7280;
}

.log-report-summary__item strong {
  font-size: 15px;
}

.log-report-section {
  border-radius: 18px;
  border: 1px solid #e5e7eb;
  background: white;
  overflow: hidden;
}

.log-report-section__header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  padding: 18px 22px;
  border-bottom: 1px solid #edf0f5;
}

.log-report-section__header h3 {
  margin: 0;
  font-size: 20px;
}

.log-report-section__count {
  padding: 6px 12px;
  border-radius: 999px;
  background: #eef2ff;
  font-size: 12px;
  font-weight: 700;
}

.log-report-section__count.is-handover {
  background: #dbeafe;
}

.log-report-section__count.is-tm {
  background: #ede9fe;
}

.log-report-section__count.is-operation {
  background: #dcfce7;
}

.log-report-section__body {
  padding: 22px;
}

.log-report-operation-content,
.log-report-note-content {
  line-height: 1.8;
  white-space: pre-wrap;
}

.log-report-empty {
  color: #9ca3af;
  font-style: italic;
}

.log-report-entry-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.log-report-entry {
  display: flex;
  gap: 18px;
}

.log-report-entry__number {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #2563eb;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  flex-shrink: 0;
}

.log-report-entry__body {
  flex: 1;
}

.log-report-entry__content {
  margin-top: 8px;
  line-height: 1.7;
}

.log-report-category {
  display: inline-flex;
  align-items: center;
  padding: 5px 11px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}

.log-report-category.is-handover {
  background: #dbeafe;
  color: #1d4ed8;
}

.log-report-category.is-tm {
  background: #ede9fe;
  color: #6d28d9;
}

.log-report-category.is-bm {
  background: #dcfce7;
  color: #15803d;
}

.log-report-category.is-cm {
  background: #fee2e2;
  color: #b91c1c;
}

.log-report-category.is-default {
  background: #f3f4f6;
}

.log-report-timeline {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.log-report-timeline-item {
  display: flex;
  gap: 18px;
}

.log-report-timeline-item__rail {
  width: 24px;
  display: flex;
  justify-content: center;
}

.log-report-timeline-item__dot {
  width: 12px;
  height: 12px;
  margin-top: 9px;
  border-radius: 50%;
  background: #2563eb;
}

.log-report-timeline-item__body {
  flex: 1;
}

.log-report-timeline-item__identity {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.log-report-entry-index {
  font-weight: 700;
}

.log-report-entry-time {
  font-weight: 700;
  color: #2563eb;
}

.log-report-timeline-item__content {
  margin-top: 10px;
  line-height: 1.8;
  white-space: pre-wrap;
}

.log-report-tag {
  margin-top: 12px;
  padding: 6px 10px;
  border: none;
  border-radius: 999px;
  background: #2563eb;
  color: white;
  cursor: pointer;
  font-size: 12px;
}

.log-report-bottom-grid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 20px;
}

.log-report-attachment-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.log-report-attachment {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  border-radius: 12px;
  background: #f8fafc;
}

.log-report-attachment__number {
  margin-left: auto;
  font-weight: 700;
  color: #64748b;
}

@media (max-width:768px){

.log-report-summary {
  padding:18px;
}

.log-report-summary__top {
  flex-direction:column;
}

.log-report-bottom-grid {
  grid-template-columns:1fr;
}

.log-report-section__body {
  padding:18px;
}

}

/* =========================================================
   업무일지 메인 목록 최종 디자인
========================================================= */


/* =========================================================
   전체 미리보기
========================================================= */

.log-preview {
  display: flex;
  width: 100%;
  min-width: 0;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: left;
}


/* =========================================================
   운전현황 · TM · 인계 한 줄
========================================================= */

.log-preview__group {
  display: grid;
  width: 100%;
  min-width: 0;
  grid-template-columns:
    90px
    minmax(0, 1fr);
  align-items: start;
  column-gap: 10px;
  margin: 0;
  padding: 4px 8px;
  border: 0;
  background: transparent;
  text-align: left;
}


/*
   제목 없는 두 번째 항목도
   첫 번째 내용과 같은 위치에 정렬
*/
.log-preview__group.has-no-title {
  grid-template-columns:
    90px
    minmax(0, 1fr);
}

.log-preview__group.has-no-title::before {
  content: "";
  display: block;
  width: 90px;
}

.log-preview__group.has-no-title
.log-preview__content {
  grid-column: 2;
}


/* =========================================================
   구역 시작 가로선
========================================================= */

.log-preview__group.is-section-start {
  margin-top: 6px;
  padding-top: 8px;
  border-top: 1px solid #cbd8e5;
}

.log-preview__group.is-section-start:first-child {
  margin-top: 0;
  padding-top: 4px;
  border-top: 0;
}


/* =========================================================
   운전현황 · TM · 인계 제목
========================================================= */

.log-preview__title {
  display: inline-flex;
  justify-content: flex-end;
  align-items: center;

  width: 120px;
  min-width: 120px;
  margin-right: 12px;

  text-align: right;
  white-space: nowrap;
  flex-shrink: 0;
}

.log-preview__group.is-operation
.log-preview__title {
  border-color: #bed7ef;
  background: #eaf2fb;
  color: #1f5fae;
}

.log-preview__group.is-maintenance
.log-preview__title {
  border-color: #bddfce;
  background: #e7f6f0;
  color: #17865f;
}

.log-preview__group.is-handover
.log-preview__title {
  border-color: #ead1a5;
  background: #fff4df;
  color: #a3680d;
}


/* =========================================================
   실제 내용 최종본

   TM 발행:
   주황 번호 | 파란 시간 | 내용

   인계사항:
   파란 번호 | 파란 시간 | 내용
========================================================= */


/* =========================================================
   번호·시간·TAG·내용 묶음
========================================================= */

.log-preview__content {
  display: flex;
  min-width: 0;

  align-items: baseline;
  flex-wrap: wrap;

  gap: 5px;

  margin: 0;
  padding: 2px 0 0;

  color: #26364b;
  text-align: left;
}


/* =========================================================
   번호 공통
========================================================= */

.log-preview__entry-number {
  display: inline-block;
  flex: 0 0 auto;

  margin: 0;
  padding: 0;

  font-size: 13px;
  font-weight: 900;
  line-height: 1.55;

  font-variant-numeric:
    tabular-nums;

  white-space: nowrap;
}


/*
  TM 발행 내역 번호
*/
.log-preview__entry-number.is-tm-number {
  color: #b87412;
}


/*
  인계사항 번호
*/
.log-preview__entry-number.is-handover-number {
  color: #1f5fae;
}


/* =========================================================
   시간

   단일 시간:
   09:05

   여러 시간:
   09:06, 14:19, 16:15

   시간 범위:
   08:37~09:46
========================================================= */

.log-preview__entry-time {
  display: inline-block;
  flex: 0 0 auto;

  margin: 0;
  padding: 0;

  color: #1f5fae;

  font-size: 13px;
  font-weight: 900;
  line-height: 1.55;

  font-variant-numeric:
    tabular-nums;

  white-space: nowrap;
}


/* =========================================================
   실제 업무내용
========================================================= */

.log-preview__text {
  display: block;
  min-width: 0;
  flex: 0 1 auto;

  margin: 0;
  padding: 0;

  color: #26364b;

  font-size: 13px;
  font-weight: 600;
  line-height: 1.55;

  text-align: left;

  white-space: normal;
  word-break: break-word;
  overflow-wrap: anywhere;
}


/* =========================================================
   TAG

   기존 스타일을 유지하면서
   번호·시간과 기준선을 맞춘다.
========================================================= */

.log-preview__content
.log-preview__tag {
  flex: 0 0 auto;
  align-self: baseline;
}


/* =========================================================
   긴 내용 줄바꿈

   번호와 시간은 고정하고
   실제 내용만 자연스럽게 다음 줄로 이동한다.
========================================================= */

@media (max-width: 900px) {
  .log-preview__content {
    gap: 4px;
  }

  .log-preview__entry-number,
  .log-preview__entry-time,
  .log-preview__text {
    font-size: 12px;
  }
}

/* =========================================================
   TGO · BCO1 · BCO2 업무일지 제목

   운전현황·TM 제목과 정확히 같은
   왼쪽 시작점과 너비를 사용한다.
========================================================= */

.log-preview__role-divider {
  display: inline-flex;
  box-sizing: border-box;

  width: 120px;
  min-width: 120px;
  min-height: 23px;

  align-items: center;
  justify-content: flex-end;
  align-self: flex-start;

  margin:
    8px
    0
    3px
    8px;

  padding: 2px 7px;

  border: 1px solid #bed7ef;
  border-radius: 6px;
  background: #f8fbff;

  color: #1f5fae;
  font-size: 10px;
  font-weight: 900;
  line-height: 1.2;

  text-align: right;
  white-space: nowrap;
}


/*
   보직 제목 아래 실제 내용은
   운전현황·TM 내용 시작 위치와 동일하게 맞춘다.
*/
.log-preview__role-divider
+ .log-preview__group {
  margin-top: 0;
  padding-top: 3px;
}


/* TGO */
.log-preview__role-divider.is-tgo {
  border-color: #bed7ef;
  background: #f8fbff;
  color: #1f5fae;
}


/* BCO1 */
.log-preview__role-divider.is-bco1 {
  border-color: #bddfce;
  background: #f9fdfb;
  color: #17865f;
}


/* BCO2 */
.log-preview__role-divider.is-bco2 {
  border-color: #d5c7e6;
  background: #fcf9ff;
  color: #74419c;
}


/* 파트장 직접 작성 */
.log-preview__role-divider.is-leader {
  border-color: #dfcfb5;
  background: #fffdf9;
  color: #8c601d;
}


/* =========================================================
   TM 발행 마지막 항목 아래 경계선
========================================================= */

.log-preview__group.is-maintenance-last {
  margin-bottom: 7px;
  padding-bottom: 8px;
  border-bottom: 1px solid #cbd8e5;
}


/* =========================================================
   TAG
========================================================= */

.log-preview__tag {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  min-height: 20px;
  padding: 0 5px;
  border: 1px solid #c9dcf3;
  border-radius: 5px;
  background: #edf5ff;
  color: #1f5fae;
  font-size: 10px;
  font-weight: 900;
  line-height: 1.4;
  white-space: nowrap;
}


/* =========================================================
   근무자 현황 파트 표시
========================================================= */

.shift-section-part {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 3px 10px;

  border-radius: 999px;

  background: #eaf3ff;
  color: #1d4ed8;

  font-size: 16px;
  font-weight: 800;

  line-height: 1;
}


/* =========================================================
   업무일지 표 세로선

   보직 오른쪽과 업무내용 왼쪽만 표시
========================================================= */

.log-table th,
.log-table td {
  border-right: 0;
  border-left: 0;
}

.log-table th:nth-child(1),
.log-table td:nth-child(1) {
  border-right: 1px solid #d9e3ed;
}

.log-table th:nth-child(5),
.log-table td:nth-child(5) {
  border-left: 1px solid #d9e3ed;
}

.log-table thead th:nth-child(1) {
  border-right-color: #cbd8e5;
}

.log-table thead th:nth-child(5) {
  border-left-color: #cbd8e5;
}

/* =========================================================
  기본 정보 - 대근 체크
========================================================= */

.substitute-work-field {
  min-width: 92px;
}

.substitute-work-check {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;

  min-height: 40px;
  padding: 0 12px;

  border: 1px solid #d1d5db;
  border-radius: 7px;

  background: #ffffff;

  color: #374151;
  font-size: 14px;
  font-weight: 700;

  cursor: pointer;
  user-select: none;
}

.substitute-work-check input {
  position: absolute;

  width: 1px;
  height: 1px;

  overflow: hidden;

  opacity: 0;
  pointer-events: none;
}

.substitute-work-check__box {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  width: 18px;
  height: 18px;

  border: 1px solid #9ca3af;
  border-radius: 5px;

  background: #ffffff;

  color: transparent;
  font-size: 13px;
  font-weight: 900;
  line-height: 1;

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;
}

.substitute-work-check:has(input:checked) {
  border-color: #2563eb;
  background: #eff6ff;
  color: #1d4ed8;
}

.substitute-work-check input:checked +
.substitute-work-check__box {
  border-color: #2563eb;
  background: #2563eb;
  color: #ffffff;
}

.substitute-work-check:focus-within {
  outline: 3px solid rgba(37, 99, 235, 0.16);
  outline-offset: 1px;
}

@media (max-width: 768px) {
  .substitute-work-field {
    min-width: 0;
  }

  .substitute-work-check {
    justify-content: flex-start;
  }
}

/* =========================================================
  업무일지 목록 - 대근 배지
========================================================= */

.log-row__author-wrap {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.substitute-work-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 20px;
  padding: 2px 7px;

  border: 1px solid #f59e0b;
  border-radius: 999px;

  background: #fffbeb;

  color: #b45309;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
}

/* =========================================================
  근무자 현황 - 대근 표시
========================================================= */

.shift-member-card__name-wrap {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.shift-member-card__substitute {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  padding: 2px 7px;

  border: 1px solid #f59e0b;
  border-radius: 999px;

  background: #fffbeb;

  color: #b45309;
  font-size: 11px;
  font-weight: 800;
  line-height: 1;
}

/* =========================================================
  업무일지 목록 구역 경계선 및 여백 최종본

  적용 대상:
  - 운전현황 → TM 발행 내역
  - TM 발행 내역 → TGO 업무일지
  - TGO → BCO1 → BCO2 업무일지

  구조:
  경계선
  ↓ 충분한 여백
  구역 제목
  ↓ 적당한 여백
  업무 내용
========================================================= */


/* =========================================================
  각 구역 기본 구조
========================================================= */

.log-preview__role-divider {
  position: relative;

  display: block;
  width: 100%;

  margin: 0;
  padding: 0;
}


/* =========================================================
  보직별 업무일지 전체 영역
========================================================= */

.log-preview__role-section {
  display: block;

  width: 100%;
  min-width: 0;

  /*
    이전 구역 내용과 다음 경계선 사이 여백
  */
  margin: 14px 0 0;

  /*
    경계선과 제목 사이 여백
  */
  padding: 13px 8px 5px;

  border-top: 1px solid #cbd8e5;
}


/* =========================================================
  첫 번째 보직 업무일지

  첫 번째 보직도 TM 발행 내역과 구분되어야 하므로
  경계선과 위쪽 여백을 동일하게 유지한다.
========================================================= */

.log-preview__role-section.is-first-role {
  margin-top: 14px;
  padding-top: 13px;

  border-top: 1px solid #cbd8e5;
}


/* =========================================================
  보직 제목

  예:
  TGO 업무일지
  BCO1 업무일지
  BCO2 업무일지
========================================================= */

.log-preview__role-section .log-preview__title {
  display: inline-flex;
  align-items: center;

  margin: 0 0 9px;
  padding: 0;

  line-height: 1.4;
}


/* =========================================================
  보직별 실제 업무 내용
========================================================= */

.log-preview__role-section .log-preview__content {
  display: block;

  width: 100%;
  min-width: 0;

  margin: 0;
  padding: 0;
}


/* =========================================================
  일반 구역 간 구분선

  운전현황 및 TM 발행 내역처럼
  role-section 바깥에서 사용되는 구역
========================================================= */

.log-preview__group + .log-preview__group {
  margin-top: 14px;
  padding-top: 13px;

  border-top: 1px solid #cbd8e5;
}


/* =========================================================
  일반 구역 제목과 내용 사이 여백
========================================================= */

.log-preview__group > .log-preview__title {
  margin-bottom: 9px;
}

/* =========================================================
  업무일지 목록 최종 보완

  1. 첫 번째 팀원 업무일지(TGO) 위 경계선
  2. 보직 및 작성자 글씨 확대
========================================================= */


/* =========================================================
  파트장 팀원 업무일지 구분 영역
========================================================= */

.log-preview__role-section {
  display: block;
  width: 100%;
  margin: 8px 0 3px;
  padding: 0 8px;
}


/*
  첫 번째 보직 업무일지 위에만
  전체 너비 경계선을 표시한다.

  현재 보직 순서상 첫 번째는 TGO이다.
*/
.log-preview__role-section.is-first-role {
  margin-top: 10px;
  padding-top: 11px;
  border-top: 1px solid #cbd8e5;
}


/*
  기존 보직 제목 디자인은 유지하면서
  wrapper 안에서는 바깥 여백을 제거한다.
*/
.log-preview__role-section
.log-preview__role-divider {
  margin: 0;
}


/* =========================================================
  왼쪽 보직 글씨
========================================================= */

.log-row__role {
  color: #22324c;
  font-size: 15px;
  font-weight: 900;
  line-height: 1.4;
  text-align: center;
}


/* =========================================================
  왼쪽 작성자 글씨
========================================================= */

.log-row__author-wrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
}

.log-row__author {
  color: #22324c;
  font-size: 15px;
  font-weight: 900;
  line-height: 1.4;
  text-align: center;
}

/* =========================================================
  업무일지 상세보기 최종 디자인
========================================================= */

.log-detail-modal {
  width: min(1180px, calc(100vw - 48px));
  max-width: 1180px;
  height: min(92vh, 980px);
}

.log-detail-modal__header {
  min-height: 66px;
  padding: 13px 20px;
}

.log-detail-modal__body {
  padding: 14px 16px 18px;
  background: #f5f7fa;
}

.log-detail-modal__footer {
  min-height: 62px;
  padding: 10px 16px;
}


/* 전체 문서 */

.shift-log-detail-document {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 12px;
}


/* 공통 카드 */

.shift-log-detail-summary,
.shift-log-detail-section {
  overflow: hidden;
  border: 1px solid #d8e1eb;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 2px 8px
    rgba(15, 23, 42, 0.035);
}


/* 영문 제목 */

.shift-log-detail-eyebrow {
  display: block;
  margin: 0 0 3px;
  color: #1f5fae;
  font-size: 9px;
  font-weight: 900;
  line-height: 1.2;
  letter-spacing: 0.13em;
}


/* 기본정보 */

.shift-log-detail-summary {
  padding: 16px;
}

.shift-log-detail-summary__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 13px;
}

.shift-log-detail-summary__header h3 {
  margin: 0;
  color: #1d2d45;
  font-size: 21px;
  font-weight: 900;
  line-height: 1.25;
}

.shift-log-detail-summary__grid {
  display: grid;
  grid-template-columns:
    repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.shift-log-detail-summary__item {
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid #e0e7ef;
  border-radius: 8px;
  background: #f8fafc;
}

.shift-log-detail-summary__item > span {
  display: block;
  margin-bottom: 3px;
  color: #758296;
  font-size: 10px;
  font-weight: 800;
}

.shift-log-detail-summary__item > strong {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  color: #203149;
  font-size: 14px;
  font-weight: 900;
}


/* 대근 */

.detail-substitute-badge {
  display: inline-flex;
  min-height: 21px;
  align-items: center;
  padding: 0 7px;
  border-radius: 999px;
  background: #fff2d8;
  color: #a7640c;
  font-size: 9px;
  font-weight: 900;
}


/* 구역 헤더 */

.shift-log-detail-section__header {
  display: flex;
  min-height: 55px;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 15px;
  border-bottom: 1px solid #e1e7ee;
  background: #f8fafc;
}

.shift-log-detail-section__header h3 {
  margin: 0;
  color: #203149;
  font-size: 16px;
  font-weight: 900;
}

.shift-log-detail-count {
  display: inline-flex;
  min-width: 38px;
  min-height: 24px;
  align-items: center;
  justify-content: center;
  padding: 0 9px;
  border-radius: 999px;
  background: #eaf2fb;
  color: #1f5fae;
  font-size: 10px;
  font-weight: 900;
}

.shift-log-detail-section__body {
  padding: 11px 15px;
}

.shift-log-detail-section__body--roles {
  padding-top: 4px;
  padding-bottom: 6px;
}


/* =========================================================
  운전현황

  번호와 내용이 같은 줄
========================================================= */

.detail-operation-list {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.detail-operation-row {
  display: flex;
  min-width: 0;
  align-items: baseline;
  gap: 6px;
  margin: 0;
  padding: 2px 0;
  color: #26384f;
  font-size: 13px;
  line-height: 1.6;
  text-align: left;
}

.detail-operation-row__number {
  flex: 0 0 auto;
  color: #1f5fae;
  font-weight: 900;
  white-space: nowrap;
}

.detail-operation-row__text {
  min-width: 0;
  color: #26384f;
  font-weight: 700;
  white-space: normal;
  word-break: break-word;
}


/* =========================================================
  TM 및 인계 업무

  1. 08:00 내용
========================================================= */

.detail-work-list {
  display: flex;
  width: 100%;
  flex-direction: column;
}

.detail-work-row {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: flex-start;
  gap: 6px;
  margin: 0;
  padding: 6px 0;
  color: #26384f;
  font-size: 13px;
  line-height: 1.6;
  text-align: left;
}

.detail-work-row
+
.detail-work-row {
  border-top: 1px solid #edf1f5;
}

.detail-work-row__number {
  flex: 0 0 auto;
  margin: 0;
  padding: 0;
  font-size: 13px;
  font-weight: 900;
  line-height: 1.6;
  white-space: nowrap;
}

.detail-work-row__number.is-tm {
  color: #b87412;
}

.detail-work-row__number.is-handover {
  color: #1f5fae;
}

.detail-work-row__main {
  display: block;
  min-width: 0;
  flex: 1 1 auto;
  margin: 0;
  padding: 0;
  color: #26384f;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.6;
  text-align: left;
  word-break: break-word;
}

.detail-work-row__time {
  display: inline;
  margin-right: 6px;
  color: #1f5fae;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.detail-work-row__tag {
  display: inline;
  width: auto;
  margin: 0 5px 0 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: #1769c2;
  font: inherit;
  font-weight: 900;
  line-height: inherit;
  vertical-align: baseline;
  cursor: pointer;
}

.detail-work-row__tag:hover {
  color: #0d4e96;
  text-decoration: underline;
}

.detail-work-row__text {
  display: inline;
  color: inherit;
  font: inherit;
  line-height: inherit;
}

.detail-work-row__continuation {
  display: block;
  margin-top: 1px;
  color: #35465c;
  font: inherit;
  line-height: 1.55;
}


/* 보직별 구역 */

.detail-role-block {
  width: 100%;
  margin: 0;
  padding: 8px 0;
}

.detail-role-block
+
.detail-role-block {
  border-top: 1px solid #d9e2eb;
}

.detail-role-block__heading {
  display: flex;
  min-height: 27px;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 2px;
}

.detail-role-block__badge {
  display: inline-flex;
  min-height: 22px;
  align-items: center;
  padding: 0 8px;
  border: 1px solid #c9d7e6;
  border-radius: 5px;
  background: #f1f5f9;
  color: #41536a;
  font-size: 10px;
  font-weight: 900;
}

.detail-role-block__badge.is-tgo {
  border-color: #a8c8f2;
  background: #eaf3ff;
  color: #1d5fae;
}

.detail-role-block__badge.is-bco1 {
  border-color: #a8d9bd;
  background: #edf9f2;
  color: #26784b;
}

.detail-role-block__badge.is-bco2 {
  border-color: #d5b9ed;
  background: #f6effc;
  color: #74419c;
}

.detail-role-block__badge.is-to {
  border-color: #d8c4ed;
  background: #f6effc;
  color: #70439a;
}

.detail-role-block__badge.is-bo1,
.detail-role-block__badge.is-bo2 {
  border-color: #edcfaa;
  background: #fff4e5;
  color: #925612;
}

.detail-role-block__badge.is-leader {
  border-color: #d9bf8e;
  background: #fff7e8;
  color: #94611c;
}

.detail-role-block__count {
  color: #8591a0;
  font-size: 9px;
  font-weight: 800;
}


/* 빈 내용 */

.detail-empty-message {
  margin: 0;
  padding: 4px 0;
  color: #8a96a5;
  font-size: 12px;
  font-weight: 600;
}


/* 비고와 첨부 */

.shift-log-detail-bottom-grid {
  display: grid;
  grid-template-columns:
    repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.detail-note-content {
  color: #324258;
  font-size: 13px;
  font-weight: 650;
  line-height: 1.65;
  white-space: pre-wrap;
  word-break: break-word;
}

.detail-attachment-list {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.detail-attachment-chip {
  display: inline-flex;
  max-width: 100%;
  min-height: 30px;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid #cddaea;
  border-radius: 7px;
  background: #eef5fc;
  color: #294b72;
  font-size: 11px;
  font-weight: 750;
}


/* 모바일 */

@media (max-width: 900px) {
  .shift-log-detail-summary__grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .shift-log-detail-bottom-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {
  .log-detail-modal {
    width: calc(100vw - 12px);
    max-width: none;
    height: calc(100vh - 12px);
  }

  .log-detail-modal__body {
    padding: 9px;
  }

  .shift-log-detail-summary__grid {
    grid-template-columns: 1fr;
  }

  .detail-operation-row,
  .detail-work-row,
  .detail-work-row__number,
  .detail-work-row__main {
    font-size: 12px;
  }
}
/* =========================================================
  업무일지 진행 상태 색상 통일

  미작성   : 회색
  작성중   : 주황색
  작성완료 : 파란색
  결재완료 : 초록색
========================================================= */


/* 미작성 */
.status-badge.is-empty,
.shift-member-card__status.is-empty {
  border-color: #cbd5e1;
  background: #f1f5f9;
  color: #64748b;
}


/* 작성중 */
.status-badge.is-writing,
.shift-member-card__status.is-writing {
  border-color: #f4c77c;
  background: #fff7e8;
  color: #a15c08;
}


/* 작성완료 */
.status-badge.is-saved,
.shift-member-card__status.is-complete {
  border-color: #b9d4f5;
  background: #eaf3ff;
  color: #1763c5;
}


/* 결재완료 */
.status-badge.is-approved,
.shift-member-card__status.is-approved {
  border-color: #a9dcc1;
  background: #eaf8f0;
  color: #188451;
}

/* =========================================================
  업무일지 상세보기 - 결재확인 버튼
========================================================= */

.approval-confirm-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 40px;
  padding: 0 18px;

  border: 1px solid #15945b;
  border-radius: 8px;

  background: #168b58;
  color: #ffffff;

  font-size: 13px;
  font-weight: 900;
  line-height: 1;

  cursor: pointer;

  box-shadow:
    0 4px 10px
    rgba(22, 139, 88, 0.16);

  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    transform 0.15s ease;
}

.approval-confirm-button:hover {
  border-color: #107347;
  background: #107347;
}

.approval-confirm-button:active {
  transform: translateY(1px);
}

.approval-confirm-button[hidden] {
  display: none !important;
}

/* =========================================================
  업무일지 상세보기 모달 너비 확대
========================================================= */

.log-detail-modal {
  width: min(1180px, calc(100vw - 48px));
  max-width: 1180px;
  height: min(92vh, 980px);
}

.log-detail-modal .modal-body {
  padding: 16px;
}

@media (max-width: 768px) {
  .log-detail-modal {
    width: calc(100vw - 16px);
    max-width: none;
    height: calc(100vh - 16px);
  }

  .log-detail-modal .modal-body {
    padding: 10px;
  }
}

.detail-document-text {
  margin: 0;
  padding: 0;

  text-align: left;
  white-space: pre-line;
}

/* =========================================================
   업무일지 작성 모달 확대
========================================================= */

.log-editor-modal {
  width: min(1450px, calc(100vw - 40px));
  max-width: 1450px;
  height: min(94vh, 1080px);
}

.log-editor-modal .modal-body{
  padding:18px;
}

@media (max-width:768px){

  .log-editor-modal{
    width:calc(100vw - 14px);
    height:calc(100vh - 14px);
    max-width:none;
  }

  .log-editor-modal .modal-body{
    padding:12px;
  }

}

/* =========================================================
  파트장 작성창 - 보직별 업무일지 구분
========================================================= */

.log-entry-role-divider-row > td {
  padding: 0 !important;
  border: 0 !important;
  background: #ffffff;
}

.log-entry-role-divider {
  display: flex;
  align-items: center;
  gap: 8px;

  min-height: 38px;
  margin-top: 12px;
  padding: 9px 12px;

  border-top: 1px solid #cfdce8;
  border-bottom: 1px solid #e3eaf1;

  background: #f8fafc;
}

.log-entry-role-divider-row.is-first-role
.log-entry-role-divider {
  margin-top: 0;
  border-top: 0;
}

.log-entry-role-divider strong {
  color: #26384f;
  font-size: 13px;
  font-weight: 900;
}

.log-entry-role-divider__count {
  color: #8390a0;
  font-size: 10px;
  font-weight: 800;
}

.log-entry-role-divider__badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-width: 48px;
  min-height: 22px;
  padding: 0 7px;

  border: 1px solid #cfd8e3;
  border-radius: 6px;

  background: #f3f6f9;
  color: #627083;

  font-size: 10px;
  font-weight: 900;
  line-height: 1;
}

.log-entry-role-divider__badge.is-tgo {
  border-color: #a9c7ec;
  background: #eaf3ff;
  color: #1f5fae;
}

.log-entry-role-divider__badge.is-bco1 {
  border-color: #b6dbc6;
  background: #edf8f2;
  color: #247248;
}

.log-entry-role-divider__badge.is-bco2 {
  border-color: #d2bee8;
  background: #f5effb;
  color: #714297;
}

.log-entry-role-divider__badge.is-leader {
  border-color: #ddc69e;
  background: #fff7e8;
  color: #8d5e18;
}

/* =========================================================
  파트장 작성창 업무일지 표 - 최종 정돈

  적용 대상
  - TM 발행 내역
  - TGO / BCO1 / BCO2 등 보직별 업무일지
  - 번호 / 시간 / 내용 정렬
========================================================= */


/* =========================================================
  표 전체
========================================================= */

#logEntryListPanel .log-entry-table-wrap {
  width: 100%;
  overflow-x: auto;

  border: 1px solid #d9e3ed;
  border-radius: 9px;

  background: #ffffff;
}

#logEntryListPanel .log-entry-table {
  width: 100%;
  min-width: 760px;

  border-collapse: collapse;
  table-layout: fixed;

  background: #ffffff;
}


/* =========================================================
  표 제목
========================================================= */

#logEntryListPanel .log-entry-table thead th {
  height: 38px;
  padding: 8px 10px;

  border: 0;
  border-bottom: 1px solid #d7e1eb;

  background: #f4f7fa;

  color: #526278;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.3;

  text-align: center;
  vertical-align: middle;
}


/* =========================================================
  열 너비 고정

  일반 업무:
  구분 96px
  시간 90px
  내용 나머지 전체
========================================================= */

#logEntryListPanel
.log-entry-table--handover
.log-entry-table__category,
#logEntryListPanel
.log-entry-table--handover
.log-entry-category-cell-wrap {
  width: 96px !important;
}

#logEntryListPanel
.log-entry-table--handover
.log-entry-table__time,
#logEntryListPanel
.log-entry-table--handover
.log-entry-time-cell {
  width: 90px !important;
}

#logEntryListPanel
.log-entry-table--handover
.log-entry-table__content,
#logEntryListPanel
.log-entry-table--handover
.log-entry-content-cell {
  width: auto !important;
}


/* =========================================================
  일반 업무 행
========================================================= */

#logEntryListPanel
.log-entry-table--handover
tbody tr:not(.log-entry-role-divider-row)
td {
  padding: 9px 10px !important;

  border: 0;
  border-bottom: 1px solid #e3e9f0;

  background: #ffffff;

  vertical-align: middle !important;
}

#logEntryListPanel
.log-entry-table--handover
tbody tr:last-child td {
  border-bottom: 0;
}


/* =========================================================
  구분 칸
========================================================= */

#logEntryListPanel
.log-entry-table--handover
.log-entry-category-cell-wrap {
  padding-right: 8px !important;
  padding-left: 8px !important;

  text-align: center !important;
  vertical-align: middle !important;
}

#logEntryListPanel
.log-entry-table--handover
.log-entry-category-cell {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  min-width: 0;
}


/* =========================================================
  시간 칸
========================================================= */

#logEntryListPanel
.log-entry-table--handover
.log-entry-time-cell {
  padding-right: 8px !important;
  padding-left: 8px !important;

  color: #29425f;
  font-size: 12px;
  font-weight: 900;
  line-height: 1.4;

  text-align: center !important;
  vertical-align: middle !important;

  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

#logEntryListPanel
.log-entry-table--handover
.log-entry-time-group-label {
  display: block;

  width: 100%;
  margin: 0;
  padding: 0;

  color: inherit;
  font: inherit;
  line-height: inherit;

  text-align: center;
  white-space: nowrap;
}


/* =========================================================
  내용 칸
========================================================= */

#logEntryListPanel
.log-entry-table--handover
.log-entry-content-cell {
  min-width: 0;
  padding-right: 14px !important;
  padding-left: 12px !important;

  text-align: left !important;
  vertical-align: middle !important;
}


/*
  번호와 내용을 한 줄 구조로 고정한다.
*/
#logEntryListPanel
.log-entry-table--handover
.log-entry-handover-line {
  display: grid !important;

  width: 100%;
  min-width: 0;

  grid-template-columns:
    28px
    minmax(0, 1fr);

  align-items: start;
  column-gap: 7px;

  margin: 0;
  padding: 0;

  color: #27384e;
  font-size: 12px;
  font-weight: 650;
