/* =========================================================
  업무일지 상세 - 가로 공간 최대 활용
========================================================= */

/* 상세 모달 폭 확대 */
#logDetailModal .modal-panel {
  width: min(1180px, calc(100vw - 32px));
  max-width: 1180px;
}

/* 상세 내용 전체 폭 사용 */
#logDetailContent {
  width: 100%;
}

.log-report-section {
  width: 100%;
}

/* 항목 목록 */
.log-report-entry-list {
  display: block;
  width: 100%;
}

/* 항목 한 줄 */
.log-report-entry {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border-bottom: 1px solid #dbe5f0;
  box-sizing: border-box;
}

/* 기존에 따로 떨어져 있던 번호 숨김 */
.log-report-entry__number {
  display: none;
}

/* 본문 전체 폭 사용 */
.log-report-entry__body {
  display: block;
  width: 100%;
  min-width: 0;
}

/* 구분 배지가 있던 줄은 숨김 */
.log-report-entry__meta {
  display: none;
}

/* 실제 내용 */
.log-report-entry__content {
  display: block;
  width: 100%;
  padding: 0;
  margin: 0;
  color: #172033;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.55;
  text-align: left;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: anywhere;
}

/* 시간과 내용을 한 줄로 정렬할 신규 구조 */
.log-report-line {
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  align-items: start;
  gap: 12px;
  width: 100%;
}

.log-report-line__time {
  color: #253858;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.55;
  text-align: center;
  white-space: nowrap;
}

.log-report-line__main {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
  width: 100%;
}

.log-report-line__number {
  flex: 0 0 auto;
  color: #0b56a6;
  font-size: 13px;
  font-weight: 800;
  line-height: 1.55;
}

.log-report-line__text {
  min-width: 0;
  flex: 1 1 auto;
  color: #172033;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.55;
  text-align: left;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: anywhere;
}

/* TAG는 내용 뒤에 자연스럽게 붙음 */
.log-report-tag {
  display: inline-flex;
  flex: 0 0 auto;
  margin-left: 6px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #0868d7;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.55;
}

/* 업무 구분 헤더 */
.log-report-group-title {
  display: flex;
  align-items: center;
  min-height: 38px;
  padding: 8px 12px;
  border-bottom: 1px solid #ccd8e6;
  background: #f4f7fb;
  color: #172033;
  font-size: 13px;
  font-weight: 800;
}

/* 모바일 */
@media (max-width: 768px) {
  #logDetailModal .modal-panel {
    width: calc(100vw - 16px);
  }

  .log-report-entry {
    padding: 9px 8px;
  }

  .log-report-line {
    grid-template-columns: 50px minmax(0, 1fr);
    gap: 8px;
  }

  .log-report-line__time,
  .log-report-line__number {
    font-size: 12px;
  }

  .log-report-line__text {
    font-size: 13px;
  }
}

/* =========================================================
  GS Shift Log 로그인 화면
========================================================= */

.login-screen {
  position: fixed;
  inset: 0;
  z-index: 1000;

  display: flex;
  align-items: center;
  justify-content: center;

  min-height: 100vh;
  padding: 24px;

  background:
    linear-gradient(
      135deg,
      rgba(15, 42, 74, 0.96),
      rgba(31, 95, 174, 0.9)
    );
}

.login-card {
  width: min(420px, 100%);

  padding: 38px 36px 30px;

  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 22px;

  background: rgba(255, 255, 255, 0.98);

  box-shadow:
    0 28px 80px
    rgba(5, 20, 40, 0.32);
}

.login-card__brand {
  margin-bottom: 30px;
  text-align: center;
}

.login-card__company {
  display: block;

  margin-bottom: 10px;

  color: #1f5fae;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.04em;
}

.login-card__brand h1 {
  margin: 0;

  color: #172033;
  font-size: 32px;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.login-card__brand p {
  margin: 8px 0 0;

  color: #6b7788;
  font-size: 13px;
  font-weight: 600;
}

.login-form {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.login-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.login-field > span {
  color: #3d4b60;
  font-size: 12px;
  font-weight: 900;
}

.login-field input {
  width: 100%;
  height: 48px;

  padding: 0 14px;

  border: 1px solid #cbd6e2;
  border-radius: 10px;

  background: #ffffff;
  color: #172033;

  font-size: 14px;
  outline: none;

  transition:
    border-color 0.16s ease,
    box-shadow 0.16s ease;
}

.login-field input:focus {
  border-color: #568ccc;

  box-shadow:
    0 0 0 4px
    rgba(31, 95, 174, 0.11);
}

.login-field input::placeholder {
  color: #9ba5b3;
}

.login-submit-button {
  width: 100%;
  height: 50px;

  margin-top: 4px;

  border: 0;
  border-radius: 10px;

  background: #1f5fae;
  color: #ffffff;

  font-size: 14px;
  font-weight: 900;

  cursor: pointer;

  transition:
    background 0.16s ease,
    transform 0.12s ease;
}

.login-submit-button:hover {
  background: #194f91;
}

.login-submit-button:active {
  transform: translateY(1px);
}

.login-submit-button:disabled {
  cursor: wait;
  opacity: 0.65;
}

.login-error {
  margin: -4px 0 0;
  padding: 10px 12px;

  border: 1px solid #efb6b6;
  border-radius: 8px;

  background: #fff1f1;
  color: #b93636;

  font-size: 12px;
  font-weight: 700;
}

.login-card__help {
  margin-top: 20px;

  color: #7c8796;
  font-size: 11px;
  text-align: center;
}

.login-screen[hidden] {
  display: none !important;
}

@media (max-width: 520px) {
  .login-screen {
    padding: 16px;
  }

  .login-card {
    padding: 30px 22px 24px;
    border-radius: 18px;
  }

  .login-card__brand h1 {
    font-size: 28px;
  }
}

