  width: 100%;
  height: 40px;
  min-height: 40px;

  padding: 0 32px 0 11px;

  border: 1px solid #c8d4e1;
  border-radius: 7px;

  background-color: #ffffff;
  color: #26364c;

  font-size: 11px;
  font-weight: 800;
}


/* =========================================================
  현재시간
========================================================= */

.log-entry-current-time-field {
  width: 116px;
  min-width: 0;
}


.log-entry-current-time-field
.current-time-check {
  position: relative;

  display: inline-flex;

  width: 100%;
  height: 40px;
  min-height: 40px;

  align-items: center;
  justify-content: center;

  gap: 7px;

  margin: 0;
  padding: 0 10px;

  border: 1px solid #c8d4e1;
  border-radius: 7px;

  background: #ffffff;
  color: #536174;

  font-size: 10px;
  font-weight: 900;
  line-height: 1;

  white-space: nowrap;

  cursor: pointer;
  user-select: none;

  transition:
    border-color 0.16s ease,
    background 0.16s ease,
    color 0.16s ease;
}


.log-entry-current-time-field
.current-time-check:hover {
  border-color: #94afd0;

  background: #f4f8fc;
}


.log-entry-current-time-field
.current-time-check:has(
  input:checked
) {
  border-color: #83aad5;

  background: #eaf2fb;
  color: #1f5fae;
}


.log-entry-current-time-field
.current-time-check input {
  position: absolute;

  width: 1px;
  height: 1px;

  overflow: hidden;

  opacity: 0;

  pointer-events: none;
}


.current-time-check__box {
  display: inline-flex;

  flex: 0 0 16px;

  width: 16px;
  height: 16px;

  align-items: center;
  justify-content: center;

  border: 1px solid #aebbc9;
  border-radius: 4px;

  background: #ffffff;
  color: transparent;

  font-size: 10px;
  font-weight: 900;
  line-height: 1;
}


.current-time-check
input:checked +
.current-time-check__box {
  border-color: #1f5fae;

  background: #1f5fae;
  color: #ffffff;
}


/* 체크 표시가 HTML에 없는 경우에도 표시 */
.current-time-check
input:checked +
.current-time-check__box::before {
  content: "✓";
}


