/*
  보직별 운전현황 목록
*/
.detail-operation-dashboard__list {
  width: 100%;

  border: 1px solid #d7e0eb;
  border-radius: 10px;

  overflow: hidden;
  background: #ffffff;
}


/*
  운전현황 한 줄
*/
.detail-operation-dashboard__row {
  display: grid;

  grid-template-columns:
    42px
    64px
    9px
    minmax(0, 1fr);

  align-items: center;

  min-height: 36px;
  padding: 7px 14px;

  column-gap: 8px;

  color: #14233a;
  background: #ffffff;
}


/*
  행 사이 구분선
*/
