  background: #dff7ec;
  color: #087b50;
}


.detail-operation-dashboard__badge.is-starting {
  background: #fff3d6;
  color: #a16600;
}


.detail-operation-dashboard__badge.is-stopped {
  background: #eceff3;
  color: #536174;
}


.detail-operation-dashboard__badge.is-abnormal {
  background: #ffe8d8;
  color: #b64a00;
}


.detail-operation-dashboard__badge.is-emergency {
  background: #fee2e2;
  color: #bb1e1e;
}


/*
  세로 구분선
*/
.detail-operation-dashboard__divider {
  color: #bac4d0;

  font-size: 11px;
  font-weight: 500;

  text-align: center;
}


/*
  운전현황 내용
*/
