> tr
> td:nth-child(4),

.log-list-section
.log-table
> thead
> tr
> th:nth-child(4) {
  width: auto !important;
  min-width: 0 !important;
}


/* 관리 */

#logTableBody
> tr
> td:nth-child(5),

.log-list-section
.log-table
> thead
> tr
> th:nth-child(5) {
