  display: flex;
  flex-direction: column;
  gap: 7px;
}

/* 첨부파일 제목 */
.global-notice-card-attachments-title {
  font-size: 12px;
  font-weight: 800;
  color: #536176;
}

/* 첨부파일 링크 */
.global-notice-attachment-link {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 7px 10px;
  border: 1px solid #d9e1ec;
  border-radius: 7px;
  background: #ffffff;
  font-size: 13px;
  font-weight: 700;
  color: #245da8;
  text-decoration: none;
}

.global-notice-attachment-link:hover {
  background: #eef5ff;
  border-color: #b8ccec;
}

/* 작성자 및 작성일 */
.global-notice-card-meta {
  margin-top: 14px;
  padding-top: 11px;
  border-top: 1px solid #e2e7ee;
  font-size: 12px;
  font-weight: 600;
  line-height: 1.5;
  color: #687588;
}

/* 수정/삭제 버튼 */
.global-notice-card-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.global-notice-card-actions button {
  min-width: 48px;
  min-height: 30px;
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 800;
}

/* 중요 공지 */
.global-notice-card[data-priority="important"] {
  border-color: #e2ad38;
  border-left: 5px solid #d89a12;
  background: #fffdf7;
}

.global-notice-card[data-priority="important"]
.global-notice-card-content {
  background: #fff8e7;
}

/* 긴급 공지 */
.global-notice-card[data-priority="urgent"] {
  border-color: #e06868;
  border-left: 5px solid #d83d3d;
  background: #fffafa;
}

.global-notice-card[data-priority="urgent"]
.global-notice-card-content {
  background: #fff0f0;
}

/* 일반 공지 */
.global-notice-card[data-priority="normal"] {
  border-left: 5px solid #5c89c7;
}

/* 모바일 */
@media (max-width: 768px) {
  .global-notice-card {
    padding: 15px 14px;
