  .global-notice-card-header {
    flex-direction: column;
    gap: 10px;
  }

  .global-notice-card-actions {
    align-self: flex-end;
  }

  .global-notice-card-title {
    font-size: 16px;
  }

  .global-notice-card-content {
    padding: 13px 14px;
    font-size: 14px;
    line-height: 1.7;
  }
}

