/* =========================================================
  시스템 관리자 모달
========================================================= */

.system-admin-panel {
  width: min(
    1180px,
    calc(100vw - 48px)
  );

  max-width: 1180px;
  height: min(
    900px,
    calc(100vh - 48px)
  );

  max-height: calc(100vh - 48px);
}


/* =========================================================
  관리자 상단
========================================================= */

.system-admin-header {
  min-height: 70px;
  padding: 14px 20px;
  background: #ffffff;
}


/* =========================================================
  관리자 탭
========================================================= */

.system-admin-tabs {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(0, 1fr)
    );

  flex: 0 0 auto;
  min-height: 68px;

  border-bottom: 1px solid #d9e2ec;
  background: #f7f9fc;
}


.system-admin-tab {
  position: relative;

  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;

  gap: 3px;

  min-width: 0;
  padding: 11px 20px;

  border-right: 1px solid #e2e8f0;

  background: transparent;
  color: #64748b;

  text-align: left;

  transition:
    background 0.16s ease,
    color 0.16s ease;
}


.system-admin-tab:last-child {
  border-right: 0;
}


.system-admin-tab::after {
  content: "";

  position: absolute;
  right: 18px;
  bottom: -1px;
  left: 18px;

  height: 3px;

  border-radius:
    999px
    999px
    0
    0;

  background: transparent;
}


.system-admin-tab:hover {
  background: #f1f6fc;
  color: #245f9e;
}


.system-admin-tab.is-active {
  background: #ffffff;
  color: #1f5fae;
}


.system-admin-tab.is-active::after {
  background: #1f5fae;
}


.system-admin-tab__title {
  color: inherit;
  font-size: 14px;
  font-weight: 900;
  line-height: 1.3;
}


.system-admin-tab small {
  color: #8a96a5;
  font-size: 10px;
  font-weight: 700;
  line-height: 1.3;
}


.system-admin-tab.is-active small {
  color: #5e7590;
}


/* =========================================================
  관리자 본문
========================================================= */

.system-admin-body {
  flex: 1 1 auto;
  min-height: 0;

  padding: 18px;

  overflow-y: auto;

  background: #f3f6f9;
}


.system-admin-view {
  display: none;
  width: 100%;
}


.system-admin-view.is-active {
  display: block;
}


.system-admin-view[hidden] {
  display: none !important;
}


/* =========================================================
  관리자 하단
========================================================= */

.system-admin-footer {
  min-height: 64px;
  padding: 11px 18px;
}


.employee-management-footer-help {
  color: #748195;
  font-size: 11px;
  font-weight: 650;
  line-height: 1.5;
}


/* =========================================================
  브랜드 관리 공통 섹션
========================================================= */

