/* =========================================================
  실제 상단 회사 브랜드
========================================================= */

.app-brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;

  min-width: 0;
}


.app-brand__logo {
  display: flex;
  align-items: center;
  justify-content: center;

  width: auto;
  min-width: 42px;
  max-width: 190px;
  height: 42px;

  padding: 0;

  overflow: hidden;

  border: 0;
  border-radius: 0;

  background: transparent;
  box-shadow: none;
}


.app-brand__fallback {
  display: grid;
  place-items: center;

  width: 42px;
  height: 42px;

  border-radius: 10px;

  background:
    linear-gradient(
      135deg,
      #1d5da8,
      #2e79c9
    );

  color: #ffffff;

  font-size: 14px;
  font-weight: 900;
}


.app-brand__logo-image {
  display: block;

  width: auto;
  max-width: 180px;
  height: 38px;

  object-fit: contain;
  object-position: left center;
}


.app-brand__logo-image[hidden],
.app-brand__fallback[hidden] {
  display: none !important;
}


.app-brand__text {
  min-width: 0;
  gap: 0;
}


.app-brand__text strong {
  overflow: hidden;

  color: #172033;

  font-size: 16px;
  font-weight: 900;
  line-height: 1.3;

  letter-spacing: -0.02em;

  text-overflow: ellipsis;
  white-space: nowrap;
}


.app-brand__text small {
  overflow: hidden;

  color: #778396;

  font-size: 10px;
  font-weight: 700;
  line-height: 1.3;

  text-overflow: ellipsis;
  white-space: nowrap;
}


/* =========================================================
  실제 로그인 화면
========================================================= */

.login-screen {
  position: fixed;
  inset: 0;
  z-index: 500;

  display: grid;
  grid-template-columns:
    minmax(0, 1.15fr)
    minmax(460px, 0.85fr);

  min-width: 0;
  min-height: 100vh;

  overflow: hidden;

  background:
    linear-gradient(
      135deg,
      #17385f,
      #2d6daf
    );
}


.login-screen__background {
  position: absolute;
  inset: 0;
  z-index: 0;

  background:
    linear-gradient(
      135deg,
      #17385f,
      #2d6daf
    );

  background-repeat: no-repeat;
  background-position: 50% 50%;
  background-size: cover;

  transform: scale(1.01);
}


.login-screen__overlay {
  position: absolute;
  inset: 0;
  z-index: 1;

  background:
    linear-gradient(
      90deg,
      rgba(8, 25, 48, 0.56) 0%,
      rgba(8, 25, 48, 0.3) 54%,
      rgba(8, 25, 48, 0.13) 100%
    );

  pointer-events: none;
}


/* =========================================================
  로그인 왼쪽 안내
========================================================= */

.login-introduction {
  position: relative;
  z-index: 2;

  display: flex;
  align-items: center;

  min-width: 0;
  min-height: 100vh;

  padding:
    clamp(50px, 7vw, 110px);
}


.login-introduction__content{

    position:absolute;

    right:120px;
    bottom:90px;

    width:360px;

    text-align:left;

    z-index:5;
}


.login-introduction__logo {
  display: flex;
  align-items: center;

  width: auto;
  max-width: 260px;
  height: 62px;

  margin-bottom: 28px;
}


.login-introduction__logo-fallback {
  display: grid;
  place-items: center;

  width: 62px;
  height: 62px;

  border: 1px solid
    rgba(255, 255, 255, 0.32);

  border-radius: 15px;

  background:
    rgba(255, 255, 255, 0.15);

  color: #ffffff;

  font-size: 19px;
  font-weight: 900;

  backdrop-filter: blur(10px);
}


.login-introduction__logo-image {
  display: block;

  width: auto;
  max-width: 250px;
  height: 60px;

  object-fit: contain;
  object-position: left center;

  filter:
    drop-shadow(
      0 5px 15px
      rgba(0, 0, 0, 0.15)
    );
}


.login-introduction__logo-image[hidden],
.login-introduction__logo-fallback[hidden] {
  display: none !important;
}


.login-introduction__company {
  margin: 0 0 9px;

  color:
    rgba(
      255,
      255,
      255,
      0.76
    );

  font-size: 13px;
  font-weight: 800;
  line-height: 1.4;
  letter-spacing: 0.02em;
}


.login-introduction__title {
  margin: 0;

  color: #ffffff;

  font-size:
    clamp(
      40px,
      5vw,
      68px
    );

  font-weight: 900;
  line-height: 1.06;
  letter-spacing: -0.055em;

  text-shadow:
    0 8px 30px
    rgba(0, 0, 0, 0.18);
}


.login-introduction__description {
  margin: 14px 0 0;

  color:
    rgba(
      255,
      255,
      255,
      0.84
    );

  font-size:
    clamp(
      15px,
      1.45vw,
      20px
    );

  font-weight: 650;
  line-height: 1.55;
}


.login-introduction__line {
  width: 44px;
  height: 3px;

  margin: 27px 0 19px;

  border-radius: 999px;

  background:
    rgba(
      255,
      255,
      255,
      0.78
    );
}


.login-introduction__notice {
  margin: 0;

  color:
    rgba(
      255,
      255,
      255,
      0.68
    );

  font-size: 12px;
  font-weight: 650;
  line-height: 1.6;
}


/* =========================================================
   로그인 카드 영역
========================================================= */

.login-screen__content{
    position:relative;
    z-index:3;

    display:flex;
    justify-content:center;
    align-items:center;

    min-height:100vh;

    width:100%;

    padding:0;

    transform:none;
}


/* =========================================================
  로그인 카드
========================================================= */

.login-card {
  width: min(430px, 100%);

  padding: 34px;

  border: 1px solid
    rgba(
      255,
      255,
      255,
      0.76
    );

  border-radius: 20px;

  background:
    rgba(
      255,
      255,
      255,
      0.95
    );

  box-shadow:
    0 28px 80px
    rgba(
      8,
      22,
      42,
      0.3
    );

  backdrop-filter: blur(18px);
}


.login-card__brand {
  display: none;
  align-items: center;
  gap: 11px;

  margin-bottom: 26px;
}


.login-card__logo {
  display: flex;
  align-items: center;
  justify-content: center;

  flex: 0 0 auto;

  min-width: 44px;
  max-width: 150px;
  height: 44px;
}


.login-card__logo-fallback {
  display: grid;
  place-items: center;

  width: 44px;
  height: 44px;

  border-radius: 10px;

  background:
    linear-gradient(
      135deg,
      #1d5da8,
      #2e79c9
    );

  color: #ffffff;

  font-size: 14px;
  font-weight: 900;
}


.login-card__logo-image {
  display: block;

  width: auto;
  max-width: 145px;
  height: 42px;

  object-fit: contain;
  object-position: left center;
}


.login-card__logo-image[hidden],
.login-card__logo-fallback[hidden] {
  display: none !important;
}


.login-card__brand-text {
  display: flex;
  min-width: 0;
  flex-direction: column;
}


.login-card__brand-text span {
  color: #8190a2;

  font-size: 9px;
  font-weight: 750;
}


.login-card__brand-text strong {
  color: #18283f;

  font-size: 15px;
  font-weight: 900;
}


.login-card__header {
  margin-bottom: 25px;
}


.login-card__eyebrow {
  margin: 0 0 6px;

  color: #1f5fae;

  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.15em;
}


.login-card__header h2 {
  margin: 0;

  color: #172033;

  font-size: 30px;
  font-weight: 900;
  line-height: 1.2;
  letter-spacing: -0.04em;
}


.login-card__header > p:last-child {
  margin: 7px 0 0;

  color: #7d8999;

  font-size: 12px;
  font-weight: 600;
}


/* =========================================================
  로그인 입력
========================================================= */

.login-form {
  display: flex;
  flex-direction: column;

  gap: 15px;
}


.login-field {
  display: flex;
  flex-direction: column;

  gap: 6px;
}


.login-field__label {
  color: #48586e;

  font-size: 11px;
  font-weight: 900;
}


.login-field__input-wrap {
  display: grid;
  grid-template-columns:
    46px
    minmax(0, 1fr);

  align-items: center;

  min-height: 50px;

  overflow: hidden;

  border: 1px solid #cbd6e2;
  border-radius: 10px;

  background: #ffffff;

  transition:
    border-color 0.16s ease,
    box-shadow 0.16s ease;
}


.login-field__input-wrap:focus-within {
  border-color: #6d9dcc;

  box-shadow:
    0 0 0 4px
    rgba(
      31,
      95,
      174,
      0.1
    );
}


.login-field__icon {
  display: flex;
  align-items: center;
  justify-content: center;

  align-self: stretch;

  border-right: 1px solid #e0e6ed;

  background: #f6f8fb;
  color: #6f7f92;

  font-size: 9px;
  font-weight: 900;
}


.login-field input {
  width: 100%;
  min-width: 0;
  height: 48px;

  padding: 0 13px;

  border: 0;
  outline: 0;

  background: transparent;
  color: #172033;

  font-size: 13px;
  font-weight: 700;
}


.login-field input::placeholder {
  color: #a1aab6;
  font-weight: 500;
}


/* =========================================================
  로그인 오류
========================================================= */

.login-error {
  margin: 0;
  padding: 10px 11px;

  border: 1px solid #e8b6b6;
  border-radius: 8px;

  background: #fff0f0;
  color: #b13c3c;

  font-size: 11px;
  font-weight: 750;
  line-height: 1.5;
}


/* =========================================================
  로그인 버튼
========================================================= */

.login-submit-button {
  display: flex;
  align-items: center;
  justify-content: center;

  min-height: 51px;
  margin-top: 3px;

  border-radius: 10px;

  background:
    linear-gradient(
      135deg,
      #1f5fae,
      #174c8d
    );

  color: #ffffff;

  font-size: 13px;
  font-weight: 900;

  box-shadow:
    0 9px 20px
    rgba(
      31,
      95,
      174,
      0.22
    );

  transition:
    transform 0.14s ease,
    filter 0.16s ease;
}


.login-submit-button:hover:not(:disabled) {
  filter: brightness(1.06);
}


.login-submit-button:active:not(:disabled) {
  transform: translateY(1px);
}


.login-submit-button:disabled {
  cursor: wait;
  opacity: 0.66;
}


/* =========================================================
  로그인 카드 하단
========================================================= */

.login-card__footer {
  display: flex;
  align-items: center;
  justify-content: center;

  gap: 7px;

  margin-top: 22px;
  padding-top: 17px;

  border-top: 1px solid #e4e9ef;

  color: #8793a3;

  font-size: 9px;
  font-weight: 700;
}


.login-card__status-dot {
  width: 6px;
  height: 6px;

  border-radius: 50%;

  background: #168b58;

  box-shadow:
    0 0 0 3px
    rgba(
      22,
      139,
      88,
      0.12
    );
}


/* =========================================================
  로그인 화면 반응형
========================================================= */

@media (max-width: 1050px) {
  .login-screen {
    grid-template-columns:
      minmax(0, 0.9fr)
      minmax(430px, 1.1fr);
  }


  .login-introduction {
    padding: 52px;
  }


  .login-introduction__title {
    font-size: 46px;
  }


  .login-screen__content {
    padding: 34px;
  }
}


@media (max-width: 780px) {
  .login-screen {
    display: block;

    overflow-y: auto;
  }


  .login-introduction {
    display: none;
  }


  .login-screen__overlay {
    background:
      rgba(
        7,
        24,
        47,
        0.42
      );
  }


  .login-screen__content {
    min-height: 100dvh;
    padding: 22px;
  }


  .login-card {
    width: min(420px, 100%);

    padding: 27px 23px;

    border-radius: 17px;
  }


  .login-card__brand {
    display: flex;
  }


  .login-card__header h2 {
    font-size: 26px;
  }
}


@media (max-width: 420px) {
  .login-screen__content {
    padding: 13px;
  }


  .login-card {
    padding: 24px 19px;
  }
}

/* =========================================================
  로그인 카드 위치 최종 보정

  반드시 style.css 맨 마지막에 배치
========================================================= */

#loginScreen .login-screen__content {
  justify-content: center;

  padding:
    42px
    0;

  /*
    음수: 왼쪽으로 이동
    양수: 오른쪽으로 이동
  */
  transform: translateX(-90px);
}

@media (max-width: 780px) {
  #loginScreen .login-screen__content {
    padding: 22px;

    transform: none;
  }
}

/* =========================================================
   로그인 화면 배치 최종 고정

   구성:
   소개 문구 | 로그인 카드

   - 로그인 카드는 화면 정중앙
   - GS Shift Log 문구는 카드 왼쪽
   - 배경 이미지 안의 회사 로고와 슬로건은 그대로 사용
========================================================= */


/* =========================================================
   로그인 화면 전체
========================================================= */

.login-screen {
  position: fixed !important;
  inset: 0 !important;
  z-index: 1000 !important;

  display: block !important;

  width: 100vw !important;
  min-width: 1180px !important;
  min-height: 100vh !important;

  padding: 0 !important;
  overflow: hidden !important;
}


/* =========================================================
   로그인 카드 영역

   화면 기준 정중앙에 고정
========================================================= */

.login-screen__content {
  position: absolute !important;

  top: 50% !important;
  left: 50% !important;
  z-index: 5 !important;

  display: flex !important;
  align-items: center !important;
  justify-content: center !important;

  width: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;

  margin: 0 !important;
  padding: 0 !important;

  transform: translate(-50%, -50%) !important;
}


/* 로그인 카드 자체 위치 흔들림 방지 */

.login-screen__content .login-card {
  position: relative !important;

  width: 430px !important;
  max-width: 430px !important;

  margin: 0 !important;

  transform: none !important;
}


/* =========================================================
   왼쪽 시스템 소개 영역

   로그인 카드 왼쪽에 위치
========================================================= */

.login-introduction {
  position: absolute !important;

  top: 50% !important;
  right: calc(50% + 255px) !important;
  z-index: 4 !important;

  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;

  width: 460px !important;
  min-width: 460px !important;
  min-height: 0 !important;

  margin: 0 !important;
  padding: 0 !important;

  transform: translateY(-50%) !important;

  pointer-events: none !important;
}


/* 소개 문구 실제 내용 */

.login-introduction__content {
  position: static !important;

  width: 430px !important;
  max-width: 430px !important;

  margin: 0 !important;
  padding: 0 !important;

  text-align: left !important;

  transform: none !important;
}


/* =========================================================
   배경 이미지에 이미 회사 로고와 슬로건이 있으므로 숨김
========================================================= */

.login-introduction__logo,
.login-introduction__company {
  display: none !important;
}


/* =========================================================
   GS Shift Log
========================================================= */

.login-introduction__title {
  width: 100% !important;

  margin: 0 !important;

  color: #ffffff !important;

  font-size: 54px !important;
  font-weight: 900 !important;
  line-height: 1.04 !important;
  letter-spacing: -0.055em !important;

  text-align: left !important;
  white-space: nowrap !important;

  text-shadow:
    0 8px 28px
    rgba(0, 0, 0, 0.22) !important;
}


/* 교대근무 업무일지 시스템 */

.login-introduction__description {
  margin: 14px 0 0 !important;

  color:
    rgba(
      255,
      255,
      255,
      0.92
    ) !important;

  font-size: 18px !important;
  font-weight: 750 !important;
  line-height: 1.45 !important;

  text-align: left !important;
  white-space: nowrap !important;
}


/* 짧은 가로선 */

.login-introduction__line {
  width: 42px !important;
  height: 3px !important;

  margin: 24px 0 17px !important;

  border-radius: 999px !important;

  background:
    rgba(
      255,
      255,
      255,
      0.86
    ) !important;
}


/* 안내 문구 */

.login-introduction__notice {
  width: 100% !important;

  margin: 0 !important;

  color:
    rgba(
      255,
      255,
      255,
      0.78
    ) !important;

  font-size: 12px !important;
  font-weight: 650 !important;
  line-height: 1.6 !important;

  text-align: left !important;
  white-space: nowrap !important;
}


/* =========================================================
   화면 폭이 조금 좁을 때
========================================================= */

@media (max-width: 1450px) {
  .login-introduction {
    right: calc(50% + 235px) !important;
    width: 400px !important;
    min-width: 400px !important;
  }

  .login-introduction__content {
    width: 370px !important;
  }

  .login-introduction__title {
    font-size: 46px !important;
  }

  .login-introduction__description {
    font-size: 16px !important;
  }
}


/* =========================================================
   모바일·태블릿

   작은 화면에서는 소개 문구를 숨기고
   로그인 카드만 중앙에 표시
========================================================= */

@media (max-width: 900px) {
  .login-screen {
    min-width: 0 !important;
  }

  .login-introduction {
    display: none !important;
  }

  .login-screen__content {
    width: calc(100% - 32px) !important;
  }

  .login-screen__content .login-card {
    width: min(430px, 100%) !important;
    max-width: 100% !important;
  }
}

/* =========================================================
  GS SHIFT LOG 모바일 UI 최종 오버라이드
  기준 화면: 768px 이하

  목적:
  - PC 최소 너비 강제 해제
  - 모바일 좌우 여백 축소
  - 헤더·탭·근무자 현황·날짜 이동 컴팩트화
  - 업무일지 모달 전체 화면화
  - 기존 중복 모바일 CSS 최종 덮어쓰기
========================================================= */

html {
  min-width: 0;
  width: 100%;
  overflow-x: hidden;
}

body {
  min-width: 0;
  width: 100%;
  overflow-x: hidden;
}

.app-shell {
  width: 100%;
  min-width: 0;
}


/* =========================================================
  태블릿 이하
========================================================= */

@media (max-width: 768px) {

  :root {
    --header-height: 56px;
  }


  /* =====================================================
    전체 기본
  ====================================================== */

  body {
    font-size: 13px;
    background: #eef2f6;
  }

  button,
  input,
  select,
  textarea {
    font-size: 13px;
  }

  .app-header__inner,
  .top-tabs__inner,
  .app-main {
    width: 100%;
    max-width: none;
    margin: 0;
  }

  .app-main {
    padding: 10px 10px 30px;
  }


  /* =====================================================
    상단 헤더
  ====================================================== */

  .app-header {
    height: 56px;
  }

  .app-header__inner {
    padding: 0 10px;
    gap: 8px;
  }

  .brand {
    min-width: 0;
    gap: 8px;
  }

  .brand__mark {
    width: 34px;
    height: 34px;
    border-radius: 9px;
  }

  .brand__text {
    min-width: 0;
  }

  .brand__text strong {
    max-width: 130px;
    overflow: hidden;
    font-size: 14px;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .brand__text small {
    max-width: 130px;
    overflow: hidden;
    font-size: 9px;
    line-height: 1.2;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .header-actions {
    gap: 2px;
  }

  .header-action {
    min-height: 32px;
    padding: 0 8px;
    font-size: 11px;
  }

  .header-user {
    gap: 3px;
    margin-left: 0;
    padding-left: 4px;
    border-left: 0;
  }

  .header-user__name {
    display: none;
  }

  .header-action--logout {
    padding-right: 4px;
    padding-left: 4px;
  }


  /* =====================================================
    상단 탭
  ====================================================== */

  .top-tabs {
    top: 56px;
  }

  .top-tabs__inner {
    height: 42px;
    padding: 0 10px;
  }

  .top-tab {
    min-width: 70px;
    padding: 0 14px;
    font-size: 12px;
  }

  .top-tab::after {
    right: 12px;
    left: 12px;
    height: 2px;
  }


  /* =====================================================
    공통 콘텐츠 카드
  ====================================================== */

  .content-section {
    margin-bottom: 10px;
    padding: 13px;
    border-radius: 13px;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 7px;
    margin-bottom: 12px;
  }

  .section-heading--with-action {
    align-items: stretch;
  }

  .section-heading__eyebrow {
    margin-bottom: 2px;
    font-size: 9px;
  }

  .section-heading__title {
    margin: 0;
    font-size: 22px;
    line-height: 1.15;
  }

  .section-heading--with-action .primary-button {
    width: 100%;
  }


  /* =====================================================
    현재 근무 표시
  ====================================================== */

  .shift-summary {
    width: 100%;
    align-items: flex-start;
    flex-direction: column;
    gap: 2px;
  }

  .shift-summary__label {
    font-size: 10px;
  }

  .shift-summary__value {
    width: 100%;
    font-size: 12px;
    line-height: 1.4;
    word-break: keep-all;
  }

  /* =====================================================
    날짜 이동
  ====================================================== */

  .date-navigation-section {
    grid-template-columns: 38px minmax(0, 1fr) 38px;
    gap: 6px;
    margin-bottom: 10px;
    padding: 9px;
    border-radius: 12px;
  }

  .date-nav-button {
    width: 38px;
    height: 38px;
    border-radius: 8px;
    font-size: 23px;
  }

  .date-navigation__center {
    min-width: 0;
    flex-direction: column;
    gap: 2px;
  }

  .date-navigation__label {
    font-size: 9px;
  }

  .date-navigation__date {
    max-width: 100%;
    gap: 6px;
  }

  .date-navigation__date strong {
    overflow: hidden;
    font-size: 13px;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .shift-badge {
    min-width: 34px;
    min-height: 22px;
    padding: 0 7px;
    font-size: 10px;
  }

  .today-button {
    grid-column: 1 / -1;
    width: 100%;
    min-height: 34px;
    font-size: 11px;
  }


  /* =====================================================
    업무일지 목록 카드
  ====================================================== */

  .log-list-section {
    padding: 12px;
  }

  .log-table-wrap {
    overflow: visible;
    border: 0;
    border-radius: 0;
    background: transparent;
  }

  .log-table {
    display: block;
    width: 100%;
    table-layout: auto;
  }

  .log-table thead {
    display: none;
  }

  .log-table tbody {
    display: flex;
    flex-direction: column;
    gap: 9px;
  }

  .log-table tbody tr {
    position: relative;
    display: grid;
    grid-template-columns:
      minmax(58px, auto)
      minmax(0, 1fr)
      auto;
    gap: 6px 8px;
    width: 100%;
    padding: 11px;
    border: 1px solid #d8e2ec;
    border-radius: 11px;
    background: #ffffff;
    box-shadow: 0 3px 10px rgba(20, 35, 55, 0.05);
  }

  .log-table tbody tr:hover {
    background: #ffffff;
  }

  .log-table td {
    display: block;
    width: auto !important;
    padding: 0 !important;
    border: 0 !important;
  }

  .log-row__role {
    grid-column: 1;
    grid-row: 1;
    align-self: center;
    text-align: left;
    font-size: 13px;
  }

  .log-row__author-cell {
    grid-column: 2;
    grid-row: 1;
    align-self: center;
    text-align: left;
  }

  .log-row__author,
  .log-row__author-wrap {
    justify-content: flex-start;
    font-size: 12px;
  }

  .log-row__status-cell {
    grid-column: 3;
    grid-row: 1;
    text-align: right;
  }

  .status-badge {
    min-width: 58px;
    min-height: 22px;
    padding: 0 7px;
    font-size: 9px;
  }

  .log-row__preview-cell {
    grid-column: 1 / -1;
    grid-row: 2;
    padding-top: 8px !important;
    border-top: 1px solid #e3e9f0 !important;
  }

  .log-row__actions-cell {
    grid-column: 1 / 3;
    grid-row: 3;
  }

  .log-row__attachment-cell {
    grid-column: 3;
    grid-row: 3;
    align-self: center;
    text-align: right;
  }

  .row-actions {
    width: auto;
    flex-direction: row;
    justify-content: flex-start;
    gap: 5px;
  }

  .table-action-button {
    width: auto;
    min-width: 62px;
    height: 30px;
    min-height: 30px;
    padding: 0 10px;
    font-size: 10px;
  }

  .attachment-indicator {
    min-width: 28px;
    min-height: 28px;
    font-size: 11px;
  }


  /* =====================================================
    목록 미리보기
  ====================================================== */

  .log-preview__group,
  .log-preview__group.has-no-title {
    display: grid;
    grid-template-columns: 68px minmax(0, 1fr);
    column-gap: 7px;
    padding: 3px 0;
  }

  .log-preview__group.has-no-title::before {
    width: 68px;
  }

  .log-preview__title {
    width: 68px !important;
    min-width: 68px !important;
    margin: 0 !important;
    justify-content: flex-start;
    font-size: 9px;
  }

  .log-preview__content {
    gap: 4px;
    padding-top: 0;
  }

  .log-preview__entry-number,
  .log-preview__entry-time,
  .log-preview__text {
    font-size: 11px;
    line-height: 1.5;
  }

  .log-preview__tag {
    min-height: 18px;
    padding: 0 4px;
    font-size: 9px;
  }

  .log-preview__role-section {
    margin-top: 7px;
    padding: 7px 0 0;
  }

  .log-preview__role-divider {
    width: auto;
    min-width: 0;
    margin: 0 0 4px;
    justify-content: flex-start;
    font-size: 9px;
  }


  /* =====================================================
    조회 검색 조건
  ====================================================== */

  .search-section {
    padding: 12px;
  }

  .search-form {
    margin-bottom: 12px;
    padding: 11px;
  }

  .search-form__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .search-form__grid .form-field--wide {
    grid-column: 1 / -1;
  }

  .form-field {
    gap: 4px;
  }

  .form-field__label {
    font-size: 10px;
  }

  .form-field input,
  .form-field select {
    min-height: 37px;
    padding: 0 9px;
    font-size: 12px;
  }

  .search-form__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 7px;
    margin-top: 10px;
  }

  .search-form__actions button {
    width: 100%;
  }


  /* =====================================================
    공통 모달
  ====================================================== */

  .modal-backdrop {
    align-items: stretch;
    padding: 0 !important;
  }

  .modal-panel {
    width: 100vw !important;
    max-width: 100vw !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
    margin: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
  }

  .modal-header {
    min-height: 56px !important;
    padding: 10px 12px !important;
  }

  .modal-header__eyebrow {
    display: none;
  }

  .modal-header__title {
    font-size: 18px;
  }

  .modal-close-button {
    width: 34px;
    height: 34px;
    border-radius: 8px;
    font-size: 22px;
  }

  .modal-body {
    padding: 10px !important;
  }

  .modal-footer {
    position: relative;
    z-index: 5;
    min-height: 58px !important;
    padding: 8px 10px !important;
    gap: 6px;
    box-shadow: 0 -5px 16px rgba(20, 35, 55, 0.08);
  }

  .modal-footer__left,
  .modal-footer__right {
    gap: 5px;
  }

  .modal-footer button {
    min-height: 38px;
    padding: 0 10px;
    font-size: 11px;
  }


  /* =====================================================
    업무일지 작성 모달
  ====================================================== */

  .log-editor-modal {
    width: 100vw !important;
    height: 100dvh !important;
  }

  .editor-section {
    margin-bottom: 9px;
    padding: 11px;
    border-radius: 10px;
  }

  .editor-section__heading {
    margin-bottom: 9px;
  }

  .editor-section__heading h3 {
    font-size: 14px;
  }

  .editor-section__heading p {
    display: none;
  }

  .basic-info-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .basic-info-field--author {
    grid-column: 1 / -1;
  }

  .substitute-work-field {
    grid-column: 1 / -1;
  }

  .substitute-work-check {
    min-height: 37px;
  }


  /* =====================================================
    운전현황
  ====================================================== */

  .operation-status-heading {
    align-items: center;
    flex-direction: row;
    gap: 8px;
  }

  .operation-status-edit-button {
    align-self: auto;
    min-height: 32px;
    padding: 0 10px;
    font-size: 10px;
  }

  .operation-status-current-card {
    padding: 11px;
    border-radius: 9px;
  }

  .operation-status-current-header {
    margin-bottom: 8px;
  }

  .operation-status-current-content {
    min-height: 58px;
    padding: 9px;
    font-size: 12px;
    line-height: 1.6;
  }

  .operation-status-current-meta {
    margin-top: 7px;
    font-size: 9px;
  }


  /* =====================================================
    작업 입력
  ====================================================== */

  .log-entry-input-panel {
    padding: 10px;
  }

  .log-entry-input-top-row {
    grid-template-columns: 1fr 1fr;
    gap: 7px;
  }

  .log-entry-field--tag {
    grid-column: 1 / -1;
  }

  .log-entry-input-actions {
    grid-column: 1 / -1;
  }

  .log-entry-input-actions button {
    flex: 1 1 0;
  }

  .log-entry-content-field {
    margin-top: 7px;
  }

  .log-entry-content-field textarea {
    min-height: 88px;
    max-height: 150px;
    font-size: 12px;
  }

  .log-entry-content-help {
    display: none;
  }


  /* =====================================================
    작성창 내 업무 목록

    우선 가로 스크롤을 최소화하고
    표 폭을 화면에 맞춘다.
  ====================================================== */

  #logEntryListPanel .log-entry-table {
    min-width: 0 !important;
    table-layout: auto;
  }

  #logEntryListPanel .log-entry-table-wrap {
    overflow-x: hidden;
  }

  #logEntryListPanel
  .log-entry-table--handover
  .log-entry-table__category,
  #logEntryListPanel
  .log-entry-table--handover
  .log-entry-category-cell-wrap,
  #logEntryListPanel
  .log-entry-table--tm
  .log-entry-table__category,
  #logEntryListPanel
  .log-entry-table--tm
  .log-entry-category-cell-wrap {
    width: 64px !important;
  }

  #logEntryListPanel
  .log-entry-table--handover
  .log-entry-table__time,
  #logEntryListPanel
  .log-entry-table--handover
  .log-entry-time-cell {
    width: 58px !important;
  }

  #logEntryListPanel .log-entry-table thead th {
    height: 34px;
    padding: 5px 4px;
    font-size: 9px;
  }

  #logEntryListPanel .log-entry-table td {
    padding: 7px 5px !important;
    font-size: 11px;
  }

  #logEntryListPanel
  .log-entry-table--handover
  .log-entry-handover-line,
  #logEntryListPanel
  .log-entry-table--tm
  .log-entry-tm-line {
    grid-template-columns: 20px minmax(0, 1fr);
    column-gap: 4px;
  }

  #logEntryListPanel
  .log-entry-table--handover
  .log-entry-handover-number,
  #logEntryListPanel
  .log-entry-table--tm
  .log-entry-tm-number {
    width: 20px;
    min-width: 20px;
    font-size: 10px;
  }

  #logEntryListPanel
  .log-entry-table--handover
  .log-entry-handover-text,
  #logEntryListPanel
  .log-entry-table--tm
  .log-entry-tm-text {
    font-size: 11px;
    line-height: 1.45;
  }

  .handover-entry-group {
    padding-right: 8px;
    padding-left: 8px;
  }

  .handover-entry-group__header {
    min-height: 40px;
    padding: 8px 0 6px;
  }

  .handover-entry-group__header strong {
    font-size: 12px;
  }

  .previous-handover-import-button,
  .previous-remark-import-button {
    min-height: 29px;
    padding: 0 8px;
    font-size: 9px;
  }


  /* =====================================================
    첨부파일
  ====================================================== */

  .file-dropzone {
    min-height: 88px;
  }

  .file-dropzone__icon {
    width: 29px;
    height: 29px;
    font-size: 18px;
  }

  .file-dropzone strong {
    font-size: 12px;
  }

  .file-dropzone small {
    display: none;
  }


  /* =====================================================
    작성창 하단 버튼
  ====================================================== */

  .log-editor-footer {
    display: grid !important;
    grid-template-columns: auto minmax(0, 1fr);
  }

  .log-editor-footer__right {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .log-editor-footer__right button {
    width: 100%;
    padding: 0 5px;
  }


  /* =====================================================
    상세보기
  ====================================================== */

  #logDetailModal .log-detail-modal {
    width: 100vw !important;
    height: 100dvh !important;
  }

  #logDetailModal .log-detail-modal__body {
    padding: 9px !important;
  }

  #logDetailModal .shift-log-detail-document {
    gap: 8px !important;
  }

  #logDetailModal .shift-log-detail-summary {
    padding: 11px;
  }

  #logDetailModal .shift-log-detail-summary__header {
    margin-bottom: 8px;
  }

  #logDetailModal .shift-log-detail-summary__header h3 {
    font-size: 17px;
  }

  #logDetailModal .shift-log-detail-summary__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 6px !important;
  }

  #logDetailModal .shift-log-detail-summary__item {
    min-height: 52px !important;
    padding: 7px 8px !important;
  }

  #logDetailModal .shift-log-detail-summary__item > span {
    font-size: 9px;
  }

  #logDetailModal .shift-log-detail-summary__item > strong {
    font-size: 12px;
  }

  #logDetailModal .shift-log-detail-section__header {
    min-height: 45px !important;
    padding: 8px 10px !important;
  }

  #logDetailModal .shift-log-detail-section__header h3 {
    font-size: 13px !important;
  }

  #logDetailModal .shift-log-detail-section__body,
  #logDetailModal .shift-log-detail-section__body--roles {
    padding: 8px 10px !important;
  }

  #logDetailModal .detail-operation-row,
  #logDetailModal .detail-work-row,
  #logDetailModal .detail-work-row__number,
  #logDetailModal .detail-work-row__main {
    font-size: 11px;
  }

  #logDetailModal .detail-work-row {
    gap: 4px;
    padding: 4px 0;
  }

  #logDetailModal .log-detail-modal__footer {
    padding: 7px 8px !important;
  }

  #logDetailModal .log-detail-footer__right {
    display: flex;
    min-width: 0;
    flex: 1 1 auto;
    justify-content: flex-end;
  }

  #logDetailModal .log-detail-footer__right button {
    min-width: 0;
    padding: 0 8px;
  }


  /* =====================================================
    토스트
  ====================================================== */

  .toast {
    right: 10px;
    bottom: 10px;
    left: 10px;
    max-width: none;
    padding: 11px 13px;
    font-size: 11px;
  }
}


/* =========================================================
  매우 작은 모바일
========================================================= */

@media (max-width: 390px) {


  .brand__text strong,
  .brand__text small {
    max-width: 108px;
  }

  .header-action {
    padding-right: 5px;
    padding-left: 5px;
    font-size: 10px;
  }

  .basic-info-grid {
    grid-template-columns: 1fr;
  }

  .basic-info-field--author,
  .substitute-work-field {
    grid-column: auto;
  }

  #logDetailModal .shift-log-detail-summary__grid {
    grid-template-columns: 1fr !important;
  }
}

/* =========================================================
  모바일 업무일지 목록 카드 최종본

  PC:
  - 기존 표 표시
  - 모바일 카드 숨김

  모바일:
  - 기존 표 숨김
  - 모바일 카드 표시
========================================================= */


/* =========================================================
  기본 상태
========================================================= */

.mobile-log-card-list {
  display: none;
}


/* =========================================================
  모바일
========================================================= */

@media (max-width: 768px) {

  /* =====================================================
    업무일지 구역
  ====================================================== */

  .log-list-section {
    padding: 12px !important;
  }


  .log-list-section
  .section-heading {
    margin-bottom: 11px !important;
  }


  .log-list-section
  .section-heading__title {
    font-size: 22px !important;
  }


  /* =====================================================
    PC 표 숨김
  ====================================================== */

  .log-list-section
  .log-table-wrap {
    display: none !important;
  }


  /* =====================================================
    빈 상태
  ====================================================== */

  .log-list-section
  .empty-state {
    padding: 28px 12px;
  }


  /* =====================================================
    모바일 목록
  ====================================================== */

  .mobile-log-card-list {
    display: flex;
    width: 100%;
    min-width: 0;
    flex-direction: column;
    gap: 9px;
  }


  .mobile-log-card-list[hidden] {
    display: none !important;
  }


  /* =====================================================
    카드
  ====================================================== */

  .mobile-log-card {
    width: 100%;
    min-width: 0;
    overflow: hidden;
    border: 1px solid #d5e0eb;
    border-radius: 11px;
    background: #ffffff;
    box-shadow:
      0 3px 10px
      rgba(20, 35, 55, 0.045);
  }


  .mobile-log-card__open {
    display: block;
    width: 100%;
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: inherit;
    text-align: left;
  }


  /* =====================================================
    카드 상단
  ====================================================== */

  .mobile-log-card__header {
    display: flex;
    min-width: 0;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 10px 11px;
    border-bottom: 1px solid #e2e8ef;
    background: #fbfcfe;
  }


  .mobile-log-card__identity {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 7px;
  }


  .mobile-log-card__role {
    flex: 0 0 auto;
    color: #1f5fae;
    font-size: 13px;
    font-weight: 900;
    line-height: 1.3;
  }


  .mobile-log-card__author {
    min-width: 0;
    overflow: hidden;
    color: #24344b;
    font-size: 13px;
    font-weight: 850;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
  }


  .mobile-log-card__substitute {
    display: inline-flex;
    flex: 0 0 auto;
    min-height: 19px;
    align-items: center;
    padding: 0 6px;
    border: 1px solid #f0be6c;
    border-radius: 999px;
    background: #fff7e8;
    color: #a25d08;
    font-size: 8px;
    font-weight: 900;
  }


  .mobile-log-card__header
  .status-badge {
    flex: 0 0 auto;
    min-width: 56px;
    min-height: 21px;
    padding: 0 7px;
    font-size: 9px;
  }


  /* =====================================================
    미리보기 전체
  ====================================================== */

  .mobile-log-card__preview {
    display: flex;
    min-width: 0;
    flex-direction: column;
    padding: 0 11px;
  }


  .mobile-log-card__empty {
    margin: 0;
    padding: 16px 0;
    color: #8a96a5;
    font-size: 11px;
    text-align: center;
  }


  /* =====================================================
    미리보기 섹션
  ====================================================== */

  .mobile-log-preview-section {
    display: grid;
    min-width: 0;
    grid-template-columns:
      72px
      minmax(0, 1fr);
    gap: 8px;
    padding: 9px 0;
  }


  .mobile-log-preview-section
  +
  .mobile-log-preview-section {
    border-top: 1px solid #e8edf3;
  }


  .mobile-log-preview-section__header {
    min-width: 0;
  }


  .mobile-log-preview-section__header
  strong {
    display: block;
    color: #485a71;
    font-size: 10px;
    font-weight: 900;
    line-height: 1.4;
    word-break: keep-all;
  }


  .mobile-log-preview-section__header
  span {
    display: block;
    margin-top: 3px;
    color: #98a2af;
    font-size: 8px;
    font-weight: 750;
  }


  .mobile-log-preview-section.is-operation
  .mobile-log-preview-section__header
  strong {
    color: #1f5fae;
  }


  .mobile-log-preview-section.is-tm
  .mobile-log-preview-section__header
  strong {
    color: #17865f;
  }


  .mobile-log-preview-section.is-handover
  .mobile-log-preview-section__header
  strong {
    color: #ad6b0c;
  }


  .mobile-log-preview-section.is-note
  .mobile-log-preview-section__header
  strong {
    color: #667181;
  }


  .mobile-log-preview-section__body {
    min-width: 0;
  }


  /* =====================================================
    미리보기 한 항목
  ====================================================== */

  .mobile-log-preview-item {
    display: grid;
    min-width: 0;
    grid-template-columns:
      18px
      minmax(0, 1fr);
    gap: 4px;
  }


  .mobile-log-preview-item
  +
  .mobile-log-preview-item {
    margin-top: 5px;
  }


  .mobile-log-preview-item__number {
    display: block;
    padding-top: 1px;
    color: #1f5fae;
    font-size: 10px;
    font-weight: 900;
    line-height: 1.45;
    text-align: right;
  }


  .mobile-log-preview-item__number.is-tm {
    color: #b87412;
  }


  .mobile-log-preview-item__main {
    min-width: 0;
  }


  .mobile-log-preview-item__line {
    display: block;
    min-width: 0;
    color: #26364b;
    font-size: 11px;
    font-weight: 650;
    line-height: 1.45;
  }


  .mobile-log-preview-item__time {
    display: inline;
    margin-right: 4px;
    color: #1f5fae;
    font-weight: 900;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }


  .mobile-log-preview-item__tag {
    display: inline;
    margin: 0 4px 0 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: #1763c5;
    font: inherit;
    font-size: 9px;
    font-weight: 900;
    line-height: inherit;
    vertical-align: baseline;
  }


  .mobile-log-preview-item__text {
    display: inline;
    color: #26364b;
    font: inherit;
    line-height: inherit;
    word-break: break-word;
    overflow-wrap: anywhere;
  }


  .mobile-log-preview-section__more {
    display: block;
    margin-top: 5px;
    color: #7c8999;
    font-size: 9px;
    font-weight: 750;
  }


  /* =====================================================
    카드 하단
  ====================================================== */

  .mobile-log-card__footer {
    display: grid;
    grid-template-columns:
      minmax(0, 1fr)
      auto
      auto;
    align-items: center;
    gap: 6px;
    padding: 8px 10px;
    border-top: 1px solid #e2e8ef;
    background: #fbfcfe;
  }


  .mobile-log-card__detail-button,
  .mobile-log-card__attachment-button,
  .mobile-log-card__edit-button {
    display: inline-flex;
    min-height: 30px;
    align-items: center;
    justify-content: center;
    padding: 0 10px;
    border-radius: 7px;
    font-size: 9px;
    font-weight: 900;
  }


  .mobile-log-card__detail-button {
    justify-self: start;
    border: 1px solid #b9cee5;
    background: #eef5fc;
    color: #1f5fae;
  }


  .mobile-log-card__attachment-button {
    border: 1px solid #d0dce9;
    background: #ffffff;
    color: #53677e;
  }


  .mobile-log-card__attachment-empty {
    color: #9ba5b1;
    font-size: 9px;
    font-weight: 700;
  }


  .mobile-log-card__edit-button {
    border: 1px solid #a9c4e2;
    background: #ffffff;
    color: #245f9e;
  }
}

/* =========================================================
  모바일 근무자 현황 최종본

  구성:
  - 7개 보직을 가로 한 줄로 표시
  - 역할 / 이름 / 상태를 세로 3단으로 표시
  - 공지는 각 칸 오른쪽 위에 작게 표시
  - 가로 스크롤 없이 화면 폭에 맞춤

  반드시 style.css 맨 마지막에 배치
========================================================= */

@media (max-width: 768px) {

  /* =====================================================
    근무자 현황 전체 카드
  ====================================================== */

  #statusView .shift-status-section {
    margin-bottom: 9px !important;
    padding: 10px 8px 9px !important;

    border-radius: 12px !important;
  }


  /* =====================================================
    제목 + 현재 근무

    두 정보를 한 줄에 배치해 상단 높이를 줄인다.
  ====================================================== */

  #statusView
  .shift-status-section
  .section-heading {
    display: grid !important;

    grid-template-columns:
      auto
      minmax(0, 1fr) !important;

    align-items: center !important;

    gap: 7px !important;

    margin-bottom: 8px !important;
  }


  #statusView
  .shift-status-section
  .section-heading__eyebrow {
    display: none !important;
  }


  #statusView
  .shift-status-section
  .section-heading__title {
    display: block !important;

    margin: 0 !important;

    color: #172033 !important;

    font-size: 16px !important;
    font-weight: 900 !important;
    line-height: 1.1 !important;
    letter-spacing: -0.04em !important;

    white-space: nowrap !important;
  }


  /*
    제목 옆에 별도로 붙는 파트 표시는 숨긴다.

    현재 근무 문구에 이미
    날짜·근무·파트가 표시된다.
  */
  #statusView
  .shift-status-section
  .shift-section-part {
    display: none !important;
  }


  /* =====================================================
    현재 날짜·근무·파트
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-summary {
    display: block !important;

    min-width: 0 !important;
    width: 100% !important;

    margin: 0 !important;
  }


  #statusView
  .shift-status-section
  .shift-summary__label {
    display: none !important;
  }


  #statusView
  .shift-status-section
  .shift-summary__value {
    display: block !important;

    width: 100% !important;
    min-width: 0 !important;

    overflow: hidden !important;

    color: #526177 !important;

    font-size: 9px !important;
    font-weight: 800 !important;
    line-height: 1.3 !important;

    text-align: right !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }


  /* =====================================================
    7명 한 줄 배치

    기존 2열 또는 1열 모바일 선언을
    7열로 최종 덮어쓴다.
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-member-grid {
    display: grid !important;

    grid-template-columns:
      repeat(
        7,
        minmax(0, 1fr)
      ) !important;

    gap: 0 !important;

    width: 100% !important;
    min-width: 0 !important;

    overflow: hidden !important;

    border: 1px solid #d6e1eb !important;
    border-radius: 9px !important;

    background: #ffffff !important;

    box-shadow:
      0 2px 8px
      rgba(20, 35, 55, 0.035) !important;
  }


  /* =====================================================
    각 보직 칸
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-member-card-wrap {
    position: relative !important;

    display: block !important;

    min-width: 0 !important;
    width: auto !important;

    margin: 0 !important;
    padding: 0 !important;

    border-right: 1px solid #e3e9f0 !important;
  }


  #statusView
  .shift-status-section
  .shift-member-card-wrap:last-child {
    border-right: 0 !important;
  }


  /*
    파트장 칸에 있던
    공지 높이 맞춤용 빈 영역 제거
  */
  #statusView
  .shift-status-section
  .role-notice-placeholder {
    display: none !important;
  }


  /* =====================================================
    업무일지 카드

    각 칸을 독립 카드처럼 보이지 않게 하고
    하나의 7칸 현황표처럼 표시한다.
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-member-card {
    position: relative !important;

    display: flex !important;

    width: 100% !important;
    min-width: 0 !important;
    min-height: 68px !important;

    flex-direction: column !important;
    align-items: center !important;
    justify-content: flex-start !important;

    margin: 0 !important;
    padding: 7px 2px 5px !important;

    overflow: hidden !important;

    border: 0 !important;
    border-radius: 0 !important;

    background: #ffffff !important;

    box-shadow: none !important;

    transform: none !important;
  }


  #statusView
  .shift-status-section
  .shift-member-card:hover,
  #statusView
  .shift-status-section
  .shift-member-card:active,
  #statusView
  .shift-status-section
  .shift-member-card:focus {
    border: 0 !important;

    background: #f8fbff !important;

    box-shadow: none !important;

    transform: none !important;
  }


  /*
    PC에서 마우스를 올렸을 때 나타나는
    "업무일지" 문구 제거
  */
  #statusView
  .shift-status-section
  .shift-member-card::after {
    display: none !important;
  }


  /* =====================================================
    보직명
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-member-card__role {
    display: block !important;

    width: 100% !important;
    min-width: 0 !important;

    margin: 0 0 4px !important;
    padding: 0 !important;

    overflow: hidden !important;

    color: #576579 !important;

    font-size: 8px !important;
    font-weight: 900 !important;
    line-height: 1.2 !important;
    letter-spacing: -0.035em !important;

    text-align: center !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }


  /* =====================================================
    이름 영역
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-member-card__body {
    display: flex !important;

    width: calc(100% - 4px) !important;
    min-width: 0 !important;
    min-height: 23px !important;

    align-items: center !important;
    justify-content: center !important;

    margin: 0 0 4px !important;
    padding: 2px 1px !important;

    border-radius: 4px !important;

    background: #f5f7fa !important;
  }


  #statusView
  .shift-status-section
  .shift-member-card__name-wrap {
    display: flex !important;

    width: 100% !important;
    min-width: 0 !important;

    align-items: center !important;
    justify-content: center !important;

    gap: 2px !important;
  }


  #statusView
  .shift-status-section
  .shift-member-card__name {
    display: block !important;

    width: 100% !important;
    min-width: 0 !important;

    overflow: hidden !important;

    color: #172033 !important;

    font-size: 10px !important;
    font-weight: 900 !important;
    line-height: 1.2 !important;
    letter-spacing: -0.07em !important;

    text-align: center !important;
    text-overflow: ellipsis !important;
    white-space: nowrap !important;
  }


  /*
    근무자 카드에서는 파트명 미표시
  */
  #statusView
  .shift-status-section
  .shift-member-card__team {
    display: none !important;
  }


  /* =====================================================
    대근 표시

    한 글자 형태로 작게 표시한다.
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-member-card__substitute {
    display: inline-flex !important;

    flex: 0 0 auto !important;

    min-width: 12px !important;
    min-height: 12px !important;

    align-items: center !important;
    justify-content: center !important;

    padding: 0 2px !important;

    border-radius: 999px !important;

    font-size: 0 !important;
    line-height: 1 !important;
  }


  #statusView
  .shift-status-section
  .shift-member-card__substitute::after {
    content: "대";

    font-size: 6px !important;
    font-weight: 900 !important;
  }


  /* =====================================================
    상태 배지 공통

    전체 문구 대신 모바일 축약 문구 표시:
    미작성
    임시
    요청
    완료
    결재
  ====================================================== */

  #statusView
  .shift-status-section
  .shift-member-card__status {
    display: inline-flex !important;

    min-width: 31px !important;
    min-height: 16px !important;

    align-items: center !important;
    justify-content: center !important;

    gap: 2px !important;

    margin: 0 !important;
    padding: 0 3px !important;

    border-radius: 999px !important;

    font-size: 0 !important;
    line-height: 1 !important;

    white-space: nowrap !important;
  }


  /*
    상태 앞의 작은 점
  */
  #statusView
  .shift-status-section
  .shift-member-card__status::before {
    width: 4px !important;
    height: 4px !important;

    margin: 0 !important;
  }


  /*
    축약 상태 글씨
  */
  #statusView
  .shift-status-section
  .shift-member-card__status::after {
    display: inline !important;

    font-size: 7px !important;
    font-weight: 900 !important;
    line-height: 1 !important;
  }


  #statusView
  .shift-status-section
  .shift-member-card__status.is-empty::after {
    content: "미작성";
  }


  #statusView
  .shift-status-section
  .shift-member-card__status.is-writing::after {
    content: "임시";
  }


  #statusView
  .shift-status-section
  .shift-member-card__status.is-requested::after {
    content: "요청";
  }


  #statusView
  .shift-status-section
  .shift-member-card__status.is-complete::after {
    content: "완료";
  }


  #statusView
  .shift-status-section
  .shift-member-card__status.is-approved::after {
    content: "결재";
  }


  /*
    결재요청 색상
  */
  #statusView
  .shift-status-section
  .shift-member-card__status.is-requested {
    border-color: #b9d4f5 !important;
    background: #eaf3ff !important;
    color: #1763c5 !important;
  }


  /* =====================================================
    공지 버튼

    각 보직 칸 오른쪽 위에 작게 배치한다.
    기존 "□ 공지" 문구는 숨기고 "공지"만 표시한다.
  ====================================================== */

  #statusView
  .shift-status-section
  .role-notice-button {
    position: absolute !important;

    top: 1px !important;
    right: 1px !important;
    z-index: 4 !important;

    display: inline-flex !important;

    width: 18px !important;
    min-width: 18px !important;
    height: 14px !important;
    min-height: 14px !important;

    align-items: center !important;
    justify-content: center !important;

    margin: 0 !important;
    padding: 0 !important;

    overflow: visible !important;

    border: 0 !important;
    border-radius: 4px !important;

    background: transparent !important;
    color: #8a96a5 !important;

    font-size: 0 !important;
    line-height: 1 !important;

    box-shadow: none !important;
  }


  #statusView
  .shift-status-section
  .role-notice-button__icon,
  #statusView
  .shift-status-section
  .role-notice-button__label {
    display: none !important;
  }


  #statusView
  .shift-status-section
  .role-notice-button::before {
    content: "공지";

    display: block !important;

    color: #8491a1 !important;

    font-size: 5.5px !important;
    font-weight: 900 !important;
    line-height: 1 !important;

    white-space: nowrap !important;
  }


  /*
    활성 공지 건수
  */
  #statusView
  .shift-status-section
  .role-notice-button__count {
    position: absolute !important;

    top: -3px !important;
    right: -2px !important;

    display: inline-flex !important;

    min-width: 9px !important;
    height: 9px !important;

    align-items: center !important;
    justify-content: center !important;

    padding: 0 2px !important;

    border: 1px solid #ffffff !important;
    border-radius: 999px !important;

    background: #1f5fae !important;
    color: #ffffff !important;

    font-size: 5px !important;
    font-weight: 900 !important;
    line-height: 1 !important;
  }


  #statusView
  .shift-status-section
  .role-notice-button__count[hidden] {
    display: none !important;
  }

}


