  color: #ffffff;
}

.arm-roll-box-search-form {
  display: grid;
  grid-template-columns:
    minmax(135px, 1fr)
    minmax(135px, 1fr)
    auto;
  align-items: end;
  gap: 7px;
}

.arm-roll-box-search-form .form-field {
  min-width: 0;
}

.arm-roll-box-search-form input {
  width: 100%;
  height: 36px;
  padding: 0 9px;
  border: 1px solid #c6d3df;
  border-radius: 7px;
  background: #ffffff;
  color: #263c52;
  font-size: 11px;
  font-weight: 800;
}

.arm-roll-box-search-form input:focus {
  border-color: #4e8ac2;
  outline: 0;
  box-shadow:
    0 0 0 3px
    rgba(
      78,
      138,
      194,
      0.12
    );
}

.arm-roll-box-search-button {
  min-width: 72px;
  height: 36px;
  padding: 0 13px;
  font-size: 11px;
  font-weight: 900;
}

.arm-roll-box-active-range {
  display: grid;
  min-width: 126px;
  gap: 2px;
  padding-left: 12px;
  border-left: 1px solid #e0e6ec;
}

.arm-roll-box-active-range span {
  color: #8090a0;
  font-size: 9px;
  font-weight: 800;
}

.arm-roll-box-active-range strong {
  color: #314b64;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.arm-roll-box-active-range small {
  color: #8090a0;
  font-size: 9px;
  font-weight: 700;
}


/* =========================================================
  현재 레벨 카드
========================================================= */

.arm-roll-box-current-grid {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(
        0,
        1fr
      )
    );
  gap: 12px;
}

.arm-roll-box-current-card {
  position: relative;
  min-width: 0;
  overflow: hidden;
  padding: 17px;
  border: 1px solid #d4dfe9;
  border-radius: 13px;
  background: #ffffff;
  box-shadow:
    0 4px 15px
    rgba(
      25,
      52,
      79,
      0.055
    );
}

.arm-roll-box-current-card::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 4px;
}

.arm-roll-box-current-card.is-arm-roll::before {
  background: #397db9;
}

.arm-roll-box-current-card.is-scrap::before {
  background: #9b6ac2;
}

.arm-roll-box-current-card.is-warning {
  border-color: #e09898;
  background:
    linear-gradient(
      135deg,
      #ffffff,
      #fff5f5
    );
}

.arm-roll-box-current-card.is-warning::before {
  background: #d84646;
}

.arm-roll-box-current-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.arm-roll-box-current-card__header > div > span {
  display: block;
  margin-bottom: 4px;
  color: #8290a0;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.11em;
}

.arm-roll-box-current-card__header > div > strong {
  display: block;
  color: #273f57;
  font-size: 14px;
  font-weight: 900;
}

.arm-roll-box-level-state {
  display: inline-flex;
  min-height: 23px;
  align-items: center;
  justify-content: center;
  padding: 0 8px;
  border: 1px solid #cbd6df;
  border-radius: 999px;
  background: #f4f7f9;
  color: #6c7a88;
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
}

.arm-roll-box-level-state.is-normal {
  border-color: #9fc9b1;
  background: #edf8f1;
  color: #25744b;
}

.arm-roll-box-level-state.is-caution {
  border-color: #e1c079;
  background: #fff7e3;
  color: #986914;
}

.arm-roll-box-level-state.is-warning {
  border-color: #df9696;
  background: #fff0f0;
  color: #b83f3f;
}

.arm-roll-box-current-level {
  display: flex;
  align-items: flex-end;
  gap: 3px;
  margin: 16px 0 11px;
}

.arm-roll-box-current-level strong {
  color: #243e57;
  font-size: 42px;
  font-weight: 900;
  line-height: 0.95;
  letter-spacing: -0.05em;
  font-variant-numeric: tabular-nums;
}

.arm-roll-box-current-level span {
  padding-bottom: 3px;
  color: #718296;
  font-size: 17px;
  font-weight: 900;
}

.arm-roll-box-current-card.is-warning
.arm-roll-box-current-level strong {
  color: #c83f3f;
}


/* =========================================================
  레벨 진행 바
========================================================= */

.arm-roll-box-level-track {
  position: relative;
  width: 100%;
  height: 11px;
  overflow: visible;
  border-radius: 999px;
  background: #e7edf2;
}

.arm-roll-box-level-fill {
  display: block;
  width: 0;
  height: 100%;
  border-radius: inherit;
  background:
    linear-gradient(
      90deg,
      #4f98ce,
      #2e75ad
    );
  transition: width 0.35s ease;
}

.arm-roll-box-current-card.is-scrap
.arm-roll-box-level-fill {
  background:
    linear-gradient(
      90deg,
      #b18bd0,
      #8a59b1
    );
}

.arm-roll-box-current-card.is-warning
.arm-roll-box-level-fill {
  background:
    linear-gradient(
      90deg,
      #e67676,
      #cf3f3f
    );
}

.arm-roll-box-level-threshold {
  position: absolute;
  top: -4px;
  bottom: -4px;
  left: 70%;
  width: 2px;
  border-radius: 2px;
  background: #d74646;
}

.arm-roll-box-level-threshold::after {
  content: "70";
  position: absolute;
  top: -16px;
  left: 50%;
  color: #c43f3f;
  font-size: 8px;
  font-style: normal;
  font-weight: 900;
  transform: translateX(-50%);
}


/* =========================================================
  현재 레벨 상세 지표
========================================================= */

.arm-roll-box-current-metrics {
  display: grid;
  grid-template-columns:
    repeat(
      2,
      minmax(
        0,
        1fr
      )
    );
  gap: 8px;
  margin: 15px 0 0;
}

.arm-roll-box-current-metrics > div {
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid #e0e7ed;
  border-radius: 8px;
  background: #f8fafc;
}

.arm-roll-box-current-metrics dt {
  margin-bottom: 3px;
  color: #7b8897;
  font-size: 8px;
  font-weight: 850;
}

.arm-roll-box-current-metrics dd {
  margin: 0;
  overflow: hidden;
  color: #334c64;
  font-size: 11px;
  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}


/* =========================================================
  공통 섹션 카드
========================================================= */

.arm-roll-box-section-card {
  min-width: 0;
  overflow: hidden;
  border: 1px solid #d4dee8;
  border-radius: 12px;
  background: #ffffff;
  box-shadow:
    0 3px 12px
    rgba(
      27,
      52,
      77,
      0.04
    );
}

.arm-roll-box-section-header {
  display: flex;
  min-height: 55px;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 15px;
  border-bottom: 1px solid #e0e6ec;
  background: #f8fafc;
}

.arm-roll-box-section-header > div {
  min-width: 0;
}

.arm-roll-box-section-header > div > span {
  display: block;
  margin-bottom: 3px;
  color: #6688a7;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
}

.arm-roll-box-section-header h4 {
  margin: 0;
  color: #294058;
  font-size: 14px;
  font-weight: 900;
}

.arm-roll-box-section-count {
  display: inline-flex;
  min-height: 25px;
  align-items: center;
  justify-content: center;
  padding: 0 8px;
  border: 1px solid #cbd7e2;
  border-radius: 999px;
  background: #ffffff;
  color: #55718b;
  font-size: 9px;
  font-weight: 900;
}


/* =========================================================
  그래프
========================================================= */

.arm-roll-box-chart-legend {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 9px;
}

.arm-roll-box-chart-legend span {
  position: relative;
  padding-left: 14px;
  color: #657589;
  font-size: 9px;
  font-weight: 800;
  white-space: nowrap;
}

.arm-roll-box-chart-legend span::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  width: 9px;
  height: 3px;
  border-radius: 999px;
  transform: translateY(-50%);
}

.arm-roll-box-chart-legend .is-arm-roll::before {
  background: #3e82bc;
}

.arm-roll-box-chart-legend .is-scrap::before {
  background: #9564ba;
}

.arm-roll-box-chart-legend .is-threshold::before {
  background: #d74c4c;
}

.arm-roll-box-chart-legend .is-replacement::before {
  height: 9px;
  border-radius: 50%;
  background: #22865f;
}

.arm-roll-box-trend-chart {
  position: relative;
  min-height: 260px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 17px;
  background: #ffffff;
}

.arm-roll-box-chart-empty {
  display: grid;
  min-height: 225px;
  place-content: center;
  color: #8a96a3;
  font-size: 11px;
  font-weight: 750;
  text-align: center;
}


/* =========================================================
  표
========================================================= */

.arm-roll-box-table-wrap {
  width: 100%;
  overflow: auto;
}

.arm-roll-box-table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
  table-layout: fixed;
}

.arm-roll-box-table th,
.arm-roll-box-table td {
  padding: 10px 9px;
  border-right: 1px solid #e4e9ee;
  border-bottom: 1px solid #e4e9ee;
  color: #3c4f62;
  font-size: 10px;
  line-height: 1.45;
  text-align: center;
  vertical-align: middle;
}

.arm-roll-box-table th:last-child,
.arm-roll-box-table td:last-child {
  border-right: 0;
}

.arm-roll-box-table th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: #eef3f7;
  color: #435b72;
  font-size: 9px;
  font-weight: 900;
  white-space: nowrap;
}

.arm-roll-box-table td {
  font-weight: 750;
}

.arm-roll-box-table tbody tr:hover td {
  background: #f8fbfd;
}

.arm-roll-box-table td.is-level-warning {
  background: #fff0f0;
  color: #be3838;
  font-weight: 900;
}

.arm-roll-box-table td.is-level-normal {
  color: #267653;
  font-weight: 900;
}

.arm-roll-box-table td.is-replacement {
  background: #edf8f2;
  color: #267653;
  font-weight: 900;
}

.arm-roll-box-table td.is-suspected {
  background: #fff7e5;
  color: #9d6913;
  font-weight: 900;
}

.arm-roll-box-empty-table-row td {
  padding: 35px 15px;
  color: #8c98a5;
  font-size: 11px;
  font-weight: 750;
}


/* =========================================================
  로딩
========================================================= */

.arm-roll-box-loading {
  position: fixed;
  z-index: 42000;
  top: 50%;
  left: 50%;
  display: flex;
  min-width: 250px;
  min-height: 56px;
  align-items: center;
  justify-content: center;
  padding: 12px 18px;
  border: 1px solid #b9cce0;
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.96);
  color: #355d84;
  font-size: 11px;
  font-weight: 900;
  box-shadow:
    0 15px 40px
    rgba(
      24,
      52,
      80,
      0.22
    );
  transform: translate(-50%, -50%);
}

.arm-roll-box-loading[hidden] {
  display: none !important;
}

.arm-roll-box-loading::before {
  content: "";
  width: 17px;
  height: 17px;
  margin-right: 9px;
  border: 3px solid #cbdceb;
  border-top-color: #3d7fb8;
  border-radius: 50%;
  animation:
    arm-roll-box-spin
    0.8s
    linear
    infinite;
}

@keyframes arm-roll-box-spin {
  to {
    transform: rotate(360deg);
  }
}


/* =========================================================
  메시지
========================================================= */

.arm-roll-box-message {
  margin: 0;
  padding: 11px 13px;
  border: 1px solid #cbd7e1;
  border-radius: 9px;
  background: #f7f9fb;
  color: #596b7d;
  font-size: 10px;
  font-weight: 800;
  line-height: 1.55;
}

.arm-roll-box-message[hidden] {
  display: none !important;
}

.arm-roll-box-message.is-error {
  border-color: #e2aaaa;
  background: #fff1f1;
  color: #a43d3d;
}

.arm-roll-box-message.is-success {
  border-color: #add2bd;
  background: #eef9f3;
  color: #27734e;
}

.arm-roll-box-message.is-warning {
  border-color: #e0c082;
  background: #fff8e8;
  color: #8d641b;
}


/* =========================================================
  태블릿
========================================================= */

@media (max-width: 1100px) {
  .arm-roll-box-query-card {
    grid-template-columns:
      minmax(
        0,
        1fr
      )
      auto;
  }

  .arm-roll-box-quick-range {
    grid-column:
      1 / -1;
  }

  .arm-roll-box-search-form {
    grid-column:
      1 / 2;
  }

  .arm-roll-box-active-range {
    grid-column:
      2 / 3;
  }
}


/* =========================================================
  모바일
========================================================= */

@media (max-width: 760px) {
  .arm-roll-box-view-heading {
    align-items: stretch;
    flex-direction: column;
    gap: 12px;
  }

  .arm-roll-box-heading-actions {
    justify-content: stretch;
  }

  .arm-roll-box-refresh-button,
  .arm-roll-box-sync-button {
    flex: 1 1 50%;
  }

  .arm-roll-box-threshold-alert {
    grid-template-columns:
      auto
      minmax(
        0,
        1fr
      );
  }

  .arm-roll-box-threshold-alert__value {
    grid-column:
      1 / -1;
    padding-left: 47px;
    font-size: 22px;
  }

  .arm-roll-box-query-card {
    display: flex;
    align-items: stretch;
    flex-direction: column;
    gap: 10px;
  }

  .arm-roll-box-quick-range {
    display: grid;
    grid-template-columns:
      repeat(
        3,
        minmax(
          0,
          1fr
        )
      );
  }

  .arm-roll-box-range-button {
    padding: 0 5px;
  }

  .arm-roll-box-search-form {
    grid-template-columns:
      repeat(
        2,
        minmax(
          0,
          1fr
        )
      );
  }

  .arm-roll-box-search-button {
    grid-column:
      1 / -1;
    width: 100%;
  }

  .arm-roll-box-active-range {
    padding-top: 9px;
    padding-left: 0;
    border-top: 1px solid #e0e6ec;
    border-left: 0;
  }

  .arm-roll-box-current-grid {
    grid-template-columns:
      minmax(
        0,
        1fr
      );
  }

  .arm-roll-box-current-level strong {
    font-size: 38px;
  }

  .arm-roll-box-section-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .arm-roll-box-chart-legend {
    gap: 6px;
  }

  .arm-roll-box-trend-chart {
    min-height: 235px;
    padding: 12px;
  }

  .arm-roll-box-table {
    min-width: 820px;
  }
}


/* =========================================================
  작은 모바일
========================================================= */

@media (max-width: 420px) {
  .arm-roll-box-current-card {
    padding: 14px;
  }

  .arm-roll-box-current-metrics {
    grid-template-columns:
      minmax(
        0,
        1fr
      );
  }

  .arm-roll-box-heading-actions {
    flex-direction: column;
  }

  .arm-roll-box-refresh-button,
  .arm-roll-box-sync-button {
    width: 100%;
  }
}

/* =========================================================
  ARM ROLL · SCRAP BOX 1·2호기 컴팩트 최종 보정

  PC:
  - 카드 4개 한 줄
  - 카드 높이 및 여백 축소
  - 내부 제목과 결과값 확대

  태블릿:
  - 카드 2개씩

  모바일:
  - 카드 1개씩
========================================================= */

.arm-roll-box-dashboard {
  gap: 10px;
  margin-top: 11px;
}


/* =========================================================
  조회 영역
========================================================= */

.arm-roll-box-query-card {
  gap: 9px;
  padding: 10px 12px;
}

.arm-roll-box-range-button {
  min-height: 32px;
  padding: 0 9px;
  font-size: 11px;
}

.arm-roll-box-search-form input,
.arm-roll-box-search-button {
  height: 34px;
  min-height: 34px;
  font-size: 12px;
}

.arm-roll-box-active-range span,
.arm-roll-box-active-range small {
  font-size: 10px;
}

.arm-roll-box-active-range strong {
  font-size: 12px;
}


/* =========================================================
  카드 4개
========================================================= */

.arm-roll-box-current-grid {
  grid-template-columns:
    repeat(
      4,
      minmax(
        0,
        1fr
      )
    );
  gap: 8px;
}

.arm-roll-box-current-card {
  padding: 12px 12px 11px;
  border-radius: 10px;
}

.arm-roll-box-current-card::before {
  width: 3px;
}


/* =========================================================
  카드 상단
========================================================= */

.arm-roll-box-current-card__header {
  gap: 8px;
}

.arm-roll-box-current-card__header > div {
  min-width: 0;
}

.arm-roll-box-current-card__header > div > span {
  margin-bottom: 3px;
  font-size: 10px;
}

.arm-roll-box-title-line {
  display: flex;
  min-width: 0;
  align-items: center;
  flex-wrap: wrap;
  gap: 5px;
}

.arm-roll-box-title-line > strong,
.arm-roll-box-current-card__header
> div
> strong {
  color: #273f57;
  font-size: 14px;
  font-weight: 900;
  line-height: 1.25;
}

.arm-roll-box-unit-badge {
  display: inline-flex;
  min-height: 21px;
  align-items: center;
  justify-content: center;
  padding: 0 7px;
  border: 1px solid #c4d4e4;
  border-radius: 999px;
  background: #f1f6fb;
  color: #365d83;
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}

.arm-roll-box-level-state {
  min-height: 22px;
  padding: 0 7px;
  font-size: 10px;
}


/* =========================================================
  현재 레벨
========================================================= */

.arm-roll-box-current-level {
  margin: 10px 0 9px;
}

.arm-roll-box-current-level strong {
  font-size: 34px;
}

.arm-roll-box-current-level span {
  padding-bottom: 2px;
  font-size: 15px;
}

.arm-roll-box-level-track {
  height: 9px;
}

.arm-roll-box-level-threshold {
  top: -3px;
  bottom: -3px;
}

.arm-roll-box-level-threshold::after {
  top: -15px;
  font-size: 9px;
}


/* =========================================================
  카드 내부 지표

  직전 측정 대비
  일평균 증가
  교체 후 경과
  최근 측정
========================================================= */

.arm-roll-box-current-metrics {
  grid-template-columns:
    repeat(
      2,
      minmax(
        0,
        1fr
      )
    );
  gap: 6px;
  margin-top: 11px;
}

.arm-roll-box-current-metrics > div {
  min-height: 55px;
  padding: 7px 8px;
  border-radius: 7px;
}

.arm-roll-box-current-metrics dt {
  margin-bottom: 3px;
  color: #6f7f91;
  font-size: 10px;
  font-weight: 900;
  line-height: 1.25;
}

.arm-roll-box-current-metrics dd {
  margin: 0;
  overflow: visible;
  color: #2e4861;
  font-size: 12px;
  font-weight: 900;
  line-height: 1.35;
  text-overflow: clip;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: anywhere;
}


/* =========================================================
  교체일과 교체 코멘트
========================================================= */

.arm-roll-box-replacement-metric {
  display: block;
}

.arm-roll-box-replacement-metric > strong {
  display: block;
  color: #2e4861;
  font-size: 13px;
  font-weight: 900;
  line-height: 1.25;
}

.arm-roll-box-replacement-metric > small {
  display: -webkit-box;
  margin-top: 3px;
  overflow: hidden;
  color: #68788a;
  font-size: 10px;
  font-weight: 750;
  line-height: 1.35;
  white-space: normal;
  word-break: keep-all;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
}


/* =========================================================
  하단 구역 글씨 확대
========================================================= */

.arm-roll-box-section-header {
  min-height: 50px;
  padding: 9px 12px;
}

.arm-roll-box-section-header > div > span {
  font-size: 9px;
}

.arm-roll-box-section-header h4 {
  font-size: 15px;
}

.arm-roll-box-section-count {
  min-height: 24px;
  font-size: 10px;
}

.arm-roll-box-chart-legend span,
.arm-roll-box-table th {
  font-size: 10px;
}

.arm-roll-box-table td {
  font-size: 11px;
}


/* =========================================================
  태블릿
========================================================= */

@media (max-width: 1180px) {
  .arm-roll-box-current-grid {
    grid-template-columns:
      repeat(
        2,
        minmax(
          0,
          1fr
        )
      );
  }
}


/* =========================================================
  모바일
========================================================= */

@media (max-width: 760px) {
  .arm-roll-box-current-grid {
    grid-template-columns:
      minmax(
        0,
        1fr
      );
  }

  .arm-roll-box-current-card {
    padding: 12px;
  }

  .arm-roll-box-current-level strong {
    font-size: 32px;
  }
}

/* ARM ROLL · SCRAP BOX 호기별 정렬 */

#armRollUnit1CurrentCard {
  order: 1;
}

#scrapUnit1CurrentCard {
  order: 2;
}

#armRollUnit2CurrentCard {
  order: 3;
}

#scrapUnit2CurrentCard {
  order: 4;
}

/* =========================================================
  ARM ROLL · SCRAP BOX 메인 교체 권고

  카드 순서:
  1호기 ARM ROLL
  1호기 SCRAP
  2호기 ARM ROLL
  2호기 SCRAP
========================================================= */


/* =========================================================
  호기별 카드 정렬
========================================================= */

#armRollUnit1CurrentCard {
  order: 1;
}

#scrapUnit1CurrentCard {
  order: 2;
}

#armRollUnit2CurrentCard {
  order: 3;
}

#scrapUnit2CurrentCard {
  order: 4;
}


/* =========================================================
  근무자 현황 오른쪽

  BOX 교체 권고 | 현재 근무
========================================================= */

.shift-heading-right {
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 14px;
}


/* =========================================================
  BOX 교체 권고 버튼
========================================================= */

.arm-roll-box-main-alert {
  display: grid;
  min-width: 250px;
  max-width: 460px;
  min-height: 48px;
  grid-template-columns:
    30px
    minmax(
      0,
      1fr
    )
    auto;
  align-items: center;
  gap: 9px;
  padding: 7px 10px;
  border: 1px solid #e1b16a;
  border-radius: 10px;
  background:
    linear-gradient(
      135deg,
      #fffaf0,
      #fff5df
    );
  color: #7e5315;
  text-align: left;
  cursor: pointer;
  box-shadow:
    0 4px 12px
    rgba(
      139,
      91,
      25,
      0.08
    );
}

.arm-roll-box-main-alert[hidden] {
  display: none !important;
}

.arm-roll-box-main-alert:hover {
  transform: translateY(-1px);
  box-shadow:
    0 6px 16px
    rgba(
      139,
      91,
      25,
      0.15
    );
}


/* 50~69% */
.arm-roll-box-main-alert.is-recommend {
  border-color: #dfa14d;
  background:
    linear-gradient(
      135deg,
      #fffaf0,
      #fff0d8
    );
  color: #80520f;
}


/* 70% 이상 */
.arm-roll-box-main-alert.is-critical {
  border-color: #e18484;
  background:
    linear-gradient(
      135deg,
      #fff5f5,
      #ffe9e9
    );
  color: #a52e2e;
  box-shadow:
    0 4px 14px
    rgba(
      190,
      53,
      53,
      0.12
    );
}


/* =========================================================
  알림 아이콘
========================================================= */

.arm-roll-box-main-alert__icon {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #df9b39;
  color: #ffffff;
  font-size: 17px;
  font-weight: 900;
}

.arm-roll-box-main-alert.is-critical
.arm-roll-box-main-alert__icon {
  background: #d94c4c;
}


/* =========================================================
  알림 내용
========================================================= */

.arm-roll-box-main-alert__content {
  display: block;
  min-width: 0;
}

.arm-roll-box-main-alert__content small {
  display: block;
  margin-bottom: 2px;
  color: inherit;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.08em;
}

.arm-roll-box-main-alert__content strong {
  display: block;
  overflow: hidden;
  color: inherit;
  font-size: 12px;
  font-weight: 900;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.arm-roll-box-main-alert__count {
  display: inline-flex;
  min-width: 35px;
  min-height: 24px;
  align-items: center;
  justify-content: center;
  padding: 0 7px;
  border: 1px solid
    rgba(
      151,
      91,
      15,
      0.24
    );
  border-radius: 999px;
  background:
    rgba(
      255,
      255,
      255,
      0.72
    );
  color: inherit;
  font-size: 10px;
  font-weight: 900;
  white-space: nowrap;
}


/* =========================================================
  좁은 PC·태블릿
========================================================= */

@media (max-width: 1150px) {
  .shift-heading-right {
    align-items: flex-end;
    flex-direction: column-reverse;
    gap: 6px;
  }

  .arm-roll-box-main-alert {
    min-width: 220px;
    max-width: 360px;
  }
}


/* =========================================================
  모바일
========================================================= */

@media (max-width: 768px) {
  #statusView
  .shift-status-section
  .shift-heading-right {
    display: flex !important;
    min-width: 0 !important;
    align-items: flex-end !important;
    flex-direction: column-reverse !important;
    justify-content: flex-end !important;
    gap: 4px !important;
  }

  #statusView
  .shift-status-section
  .arm-roll-box-main-alert {
    min-width: 0;
    width: 100%;
    max-width: 220px;
    min-height: 34px;
    grid-template-columns:
      22px
      minmax(
        0,
        1fr
      )
      auto;
    gap: 5px;
    padding: 4px 6px;
    border-radius: 7px;
  }

  #statusView
  .arm-roll-box-main-alert__icon {
    width: 21px;
    height: 21px;
    font-size: 12px;
  }

  #statusView
  .arm-roll-box-main-alert__content small {
    display: none;
  }

  #statusView
  .arm-roll-box-main-alert__content strong {
    font-size: 9px;
  }

  #statusView
  .arm-roll-box-main-alert__count {
    min-width: 29px;
    min-height: 20px;
    padding: 0 5px;
    font-size: 8px;
  }
}

/* =========================================================
  BOX 교체 권고 우측 여백 배치

  넓은 PC:
  - 본문 오른쪽 남는 공간에 컴팩트하게 표시
  - 스크롤해도 우측에 유지

  여백이 부족한 화면:
  - 기존 근무자 현황 제목 옆 위치 유지
========================================================= */

@media (min-width: 1840px) {

  /*
    알림이 빠져나간 뒤
    현재 근무 정보만 오른쪽에 정렬한다.
  */
  .shift-heading-right {
    flex: 0 0 auto !important;
  }


  /* =====================================================
    우측 BOX 교체 권고
  ====================================================== */

  .arm-roll-box-main-alert {
    position: fixed !important;

    /*
      헤더 72px
      상단 탭 52px
      메인 위쪽 여백을 고려한 위치
    */
    top: 154px !important;

    /*
      본문 최대폭 1480px의 오른쪽 끝에서
      약 12px 떨어진 위치
    */
    right:
      max(
        12px,
        calc(
          (
            100vw -
            1480px
          ) /
          2 -
          222px
        )
      ) !important;

    z-index: 60 !important;

    width:
      clamp(
        150px,
        calc(
          (
            100vw -
            1480px
          ) /
          2 -
          24px
        ),
        210px
      ) !important;

    min-width: 0 !important;
    max-width: 210px !important;
    min-height: 58px !important;

    grid-template-columns:
      25px
      minmax(
        0,
        1fr
      ) !important;

    gap: 7px !important;

    padding:
      8px
      9px !important;

    border-radius: 10px !important;

    box-shadow:
      0 5px 16px
      rgba(
        179,
        55,
        55,
        0.13
      ) !important;
  }


  /* =====================================================
    아이콘
  ====================================================== */

  .arm-roll-box-main-alert__icon {
    width: 25px !important;
    height: 25px !important;

    font-size: 14px !important;
  }


  /* =====================================================
    문구
  ====================================================== */

  .arm-roll-box-main-alert__content {
    min-width: 0 !important;
  }


  .arm-roll-box-main-alert__content small {
    margin-bottom: 2px !important;

    font-size: 8px !important;
    line-height: 1.1 !important;

    letter-spacing: 0.06em !important;
  }


  .arm-roll-box-main-alert__content strong {
    display: -webkit-box !important;

    overflow: hidden !important;

    font-size: 10px !important;
    line-height: 1.35 !important;

    white-space: normal !important;
    word-break: keep-all !important;
    overflow-wrap: anywhere !important;

    -webkit-box-orient: vertical !important;
    -webkit-line-clamp: 2 !important;
    line-clamp: 2;
  }


/* =====================================================
  건수

  오른쪽 상단 작은 배지로 표시
====================================================== */

.arm-roll-box-main-alert__count {
  position: absolute !important;

  top: 6px !important;
  right: 7px !important;
  bottom: auto !important;

  min-width: 27px !important;
  min-height: 18px !important;

  padding:
    0
    5px !important;

  border-radius: 999px !important;

  font-size: 8px !important;
  line-height: 1 !important;

  z-index: 2 !important;
}


/*
  상단의 BOX 교체 권고 문구와
  건수 배지가 겹치지 않도록 여백 확보
*/
.arm-roll-box-main-alert__content small {
  padding-right: 31px !important;
}


/*
  본문과 일정 문구는 오른쪽 공간을
  모두 사용할 수 있도록 기존 여백 제거
*/
.arm-roll-box-main-alert__content strong {
  padding-right: 0 !important;
}
}

/* =====================================================
   효율팀 빈 화면 안내 문구
===================================================== */

