====================================================== */

#efficiencyDailyWorkPaper
.efficiency-daily-work-instruction-field.is-efficiency-spreadsheet-active,

#efficiencyDailyWorkPaper
.efficiency-daily-work-other-field.is-efficiency-spreadsheet-active {
  border-radius: 4px;
}


/* =====================================================
  여러 셀 붙여넣기 완료 표시
====================================================== */

#efficiencyDailyWorkPaper
.is-efficiency-spreadsheet-pasted {
  animation:
    efficiencySpreadsheetPasteFlash
    0.9s
    ease;
}


@keyframes efficiencySpreadsheetPasteFlash {
  0% {
    box-shadow:
      inset 0 0 0 2px #1c9b62,
      inset 0 0 0 4px rgba(28, 155, 98, 0.15);
  }

  100% {
    box-shadow:
      inset 0 0 0 2px transparent,
      inset 0 0 0 4px transparent;
  }
}


