====================================================== */

@media print {

  #efficiencyDailyWorkPaper
  .is-efficiency-spreadsheet-active,

  #efficiencyDailyWorkPaper
  .is-efficiency-spreadsheet-pasted {
    box-shadow: none !important;

    animation: none !important;
  }


  #efficiencyDailyWorkPaper
  .is-efficiency-spreadsheet-active
  input,

  #efficiencyDailyWorkPaper
  .is-efficiency-spreadsheet-active
  select,

  #efficiencyDailyWorkPaper
  .is-efficiency-spreadsheet-active
