  }


  .arm-roll-box-unit-metric-cell > strong {
    font-size: 22px !important;
  }


  .arm-roll-box-unit-metric-cell > small,
  .arm-roll-box-unit-metric-cell > em {
    font-size: 13px !important;
  }


  .arm-roll-box-unit-event-cell {
    width: 88px !important;
    min-width: 88px !important;
  }
}